final authNotifierProvider =
    AsyncNotifierProvider<AuthNotifier, AuthState>(AuthNotifier.new);

// ─────────────────────────────────────────────────────────────────────────────

class AuthNotifier extends AsyncNotifier<AuthState>
    with ActionNotifierMixin<AuthState> {
  AuthRepository get _repo => ref.read(authRepositoryProvider);

  @override
  FutureOr<AuthState> build() async {
    // App start: restore the session from the stored refresh token
    // (isLoggedIn refreshes the access token when one exists).
    final loggedIn = await _repo.isLoggedIn();
    if (!loggedIn) return const AuthState();
    return AuthState(
      authenticated: true,
      userId: await _repo.currentUserId(),
    );
  }

  Future<void> login({required String email, required String password}) {
    return runAction((_) async {
      await _repo.login(email: email, password: password);
      return AuthState(
        authenticated: true,
        userId: await _repo.currentUserId(),
      );
    });
  }

  Future<void> register({required String email, required String password}) {
    return runAction((_) async {
      await _repo.register(email: email, password: password);
      return AuthState(
        authenticated: true,
        userId: await _repo.currentUserId(),
      );
    });
  }

  Future<void> logout() {
    return runAction((_) async {
      await _repo.logout();
      return const AuthState();
    });
  }

  Future<void> deleteAccount() {
    return runAction((_) async {
      await _repo.deleteAccount();
      return const AuthState(success: 'Account deleted');
    });
  }
}

import 'dart:async';
import '../../core/errors/app_exception.dart';
import 'package:dio/dio.dart';
import 'package:connectivity_plus/connectivity_plus.dart';


Future<T> safeApiCall<T>({
  required Future<T> Function() apiCall,
  FutureOr<T>? Function()? onNoInternet, // optional cache fallback
}) async {
  final connectivityResult = await Connectivity().checkConnectivity();

  if (connectivityResult.contains(ConnectivityResult.none)) {
    if (onNoInternet != null) {
      final fallback = await onNoInternet();
      if (fallback != null) return fallback;
    }
    throw AppException.noInternet();
  }

  try {
    return await apiCall();
  } on DioException catch (e) {
    throw AppException.fromDioError(e);
  } catch (e, s) {
    throw AppException.fromError(e, s);
  }
}

