/// Firebase Cloud Messaging (FCM) push notifications.
///
/// Setup:
/// 1. Create a Firebase project and run: flutterfire configure
/// 2. iOS: enable the Push Notifications and Background Modes (remote
///    notifications) capabilities in Xcode, and upload your APNs key to
///    Firebase console → Project settings → Cloud Messaging.
/// 3. Android: no extra setup — google-services.json from flutterfire is enough.
///
/// Test it from Firebase console → Messaging → New campaign.

// ─── Background handler (must be top-level) ──────────────────────────────────
@pragma('vm:entry-point')
Future<void> _firebaseBackgroundHandler(RemoteMessage message) async {
  // Runs in its own isolate. If you need other Firebase services here,
  // initialize Firebase first: await Firebase.initializeApp();
  appLogger.i('[FCM] Background message | id: ${message.messageId}');
}

/// Read this to reach the service:
/// `ref.read(firebaseNotificationsServiceProvider)`.
final firebaseNotificationsServiceProvider =
    Provider<FirebaseNotificationsService>((ref) {
  return FirebaseNotificationsService(ref);
});

class FirebaseNotificationsService {
  FirebaseNotificationsService(this._ref);

  /// Kept for reading other providers when needed (e.g. navigate on tap:
  /// `_ref.read(routerProvider).go(...)`).
  // ignore: unused_field
  final Ref _ref;

  bool _initialized = false;

  FirebaseMessaging get _messaging => FirebaseMessaging.instance;

  /// The current FCM registration token — send it to your backend so it can
  /// target this device.
  Future<String?> get token => _messaging.getToken();

  Future<void> init() async {
    if (_initialized) return;

    // Safe if Firebase was already initialized elsewhere (e.g. Crashlytics).
    // Pass DefaultFirebaseOptions.currentPlatform after `flutterfire configure`.
    if (Firebase.apps.isEmpty) {
      await Firebase.initializeApp();
    }

    FirebaseMessaging.onBackgroundMessage(_firebaseBackgroundHandler);

    // iOS: show the system banner while the app is in the foreground.
    await _messaging.setForegroundNotificationPresentationOptions(
      alert: true,
      badge: true,
      sound: true,
    );

    // Message that opened the app from a terminated state.
    final initialMessage = await _messaging.getInitialMessage();
    if (initialMessage != null) _onMessageOpened(initialMessage);

    FirebaseMessaging.onMessage.listen(_onForegroundMessage);
    FirebaseMessaging.onMessageOpenedApp.listen(_onMessageOpened);

    _messaging.onTokenRefresh.listen((token) {
      appLogger.i('[FCM] Token refreshed');
      // TODO: send the new token to your backend.
    });

    _initialized = true;
    appLogger.i('[FCM] Initialized');

    await requestPermissions();
  }

  /// Request notification permissions from the user.
  /// Returns true if granted (or provisionally granted on iOS).
  Future<bool> requestPermissions() async {
    final settings = await _messaging.requestPermission(
      alert: true,
      badge: true,
      sound: true,
    );
    return settings.authorizationStatus == AuthorizationStatus.authorized ||
        settings.authorizationStatus == AuthorizationStatus.provisional;
  }

  /// Receive messages sent to a topic (server side: send to /topics/<topic>).
  Future<void> subscribeToTopic(String topic) =>
      _messaging.subscribeToTopic(topic);

  Future<void> unsubscribeFromTopic(String topic) =>
      _messaging.unsubscribeFromTopic(topic);

  void _onForegroundMessage(RemoteMessage message) {
    appLogger.i(
      '[FCM] Foreground message | title: ${message.notification?.title}',
    );
    // Android shows no system notification for foreground messages.
    // If you also generated the local NotificationService, display one manually:
    // _ref.read(notificationServiceProvider).show(
    //   title: message.notification?.title ?? '',
    //   body: message.notification?.body ?? '',
    //   payload: message.data.toString(),
    // );
  }

  void _onMessageOpened(RemoteMessage message) {
    appLogger.i('[FCM] Opened from notification | data: ${message.data}');
    // TODO: navigate based on message.data.
  }
}

import 'package:flutter/cupertino.dart';
import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

import '../../../core/constants/app_constants.dart';
import '../../../core/utils/extensions.dart';

/// The iOS convention for a wheel picker: a Cancel / Done bar above the wheel,
/// on a sheet the caller pops with whatever the wheel was showing.
///
/// Used by [AppDateInput] and [AppTimeInput] on every platform but Android, and
/// reusable for any other wheel — drop a [CupertinoPicker] in as the [child]:
///
/// ```dart
/// showModalBottomSheet<String>(
///   context: context,
///   backgroundColor: Colors.transparent,
///   builder: (sheetContext) => CupertinoPickerSheet(
///     accent: Theme.of(context).colorScheme.primary,
///     onCancel: () => Navigator.pop(sheetContext),
///     onDone: () => Navigator.pop(sheetContext, pending),
///     child: CupertinoPicker(...),
///   ),
/// );
/// ```
///
/// It stays on Material surface colors rather than Cupertino's own, so the
/// sheet matches the rest of the app instead of the rest of iOS.
class CupertinoPickerSheet extends StatelessWidget {
  const CupertinoPickerSheet({
    super.key,
    required this.child,
    required this.accent,
    required this.onCancel,
    required this.onDone,
    this.wheelHeight = _defaultWheelHeight,
  });

  /// The wheel itself — a [CupertinoDatePicker] or a [CupertinoPicker].
  final Widget child;

  /// Colors the confirm action. Pass the variant color of the field that
  /// opened the sheet so the two read as one control.
  final Color accent;

  /// Dismiss without a value. Pop the sheet with nothing.
  final VoidCallback onCancel;

  /// Confirm. Pop the sheet with the value the wheel last reported.
  final VoidCallback onDone;

  /// A wheel is not laid out from its content, so it needs a height. 216 is
  /// what iOS gives one; raise it for a wheel with more columns.
  final double wheelHeight;

  static const double _defaultWheelHeight = 216;

  @override
  Widget build(BuildContext context) {
    final theme = context.theme;
    final localizations = MaterialLocalizations.of(context);

    return Container(
      decoration: BoxDecoration(
        color: theme.colorScheme.surface,
        borderRadius: const BorderRadius.vertical(
          top: Radius.circular(AppConstants.radius24),
        ),
      ),
      child: SafeArea(
        top: false,
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                CupertinoButton(
                  onPressed: () {
                    HapticFeedback.selectionClick();
                    onCancel();
                  },
                  child: Text(
                    localizations.cancelButtonLabel,
                    style: theme.textTheme.bodyLarge?.copyWith(
                      color: theme.colorScheme.onSurfaceVariant,
                    ),
                  ),
                ),
                CupertinoButton(
                  // The haptic for a confirmed pick belongs to whoever acts on
                  // the value, so this one only reports it.
                  onPressed: onDone,
                  child: Text(
                    localizations.okButtonLabel,
                    style: theme.textTheme.bodyLarge?.copyWith(
                      color: accent,
                      fontWeight: FontWeight.bold,
                    ),
                  ),
                ),
              ],
            ),
            Divider(height: 1, color: theme.colorScheme.outlineVariant),
            SizedBox(
              height: wheelHeight,
              child: MediaQuery(
                // The wheel has a fixed height, so a large text scale would
                // clip its rows instead of growing the sheet.
                data: MediaQuery.of(context).copyWith(
                  textScaler: TextScaler.noScaling,
                  alwaysUse24HourFormat: true,
                ),
                child: CupertinoTheme(
                  // The wheel paints its labels from the Cupertino theme, not
                  // the Material one — without this they stay dark in dark mode.
                  data: CupertinoThemeData(
                    brightness: theme.brightness,
                    primaryColor: accent,
                  ),
                  child: child,
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }
}

import 'package:flutter/foundation.dart';

/// A country the phone field can be set to: its ISO code, its calling code and
/// the shapes its national numbers are allowed to take.
///
/// Numbering plans are not all fixed-width, which is the whole reason [masks]
/// is a list rather than a string. It holds every shape a country allows,
/// narrowest first — Hungary takes 8 or 9 digits, Germany 10 through 13 — so a
/// field can grow through them as the user types instead of locking into the
/// first one.
///
/// Masks describe the *national* number only. The calling code lives in [dial]
/// because it belongs to the country selector, not to the text field.
@immutable
class AppCountry {
  /// Creates a country entry. The shipped table is [AppCountries.all]; build
  /// one of these directly only to add a country the table is missing.
  const AppCountry(this.iso, this.dial, this.name, this.masks);

  /// ISO 3166-1 alpha-2, upper case: `PT`.
  final String iso;

  /// E.164 calling code without its `+`: `351`.
  ///
  /// Territories that share a code carry the full prefix that identifies them,
  /// so the British Virgin Islands is `1284` rather than `1`. That keeps
  /// [AppCountries.byDialCode] able to tell them apart, and it is what the
  /// selector shows.
  final String dial;

  /// English country name — what the picker lists and what [matches] searches.
  final String name;

  /// National-number masks, one `#` per digit, narrowest first. Never empty.
  final List<String> masks;

  /// The flag, derived from [iso] rather than stored: an ASCII letter maps onto
  /// its regional indicator symbol, and a pair of those renders as a flag. No
  /// image assets, and nothing to keep in sync with the table.
  String get flag => String.fromCharCodes([
    for (final unit in iso.toUpperCase().codeUnits) unit + _regionalIndicator,
  ]);

  /// `+351` — what the selector shows and what [e164] starts with.
  String get dialCode => '+$dial';

  /// Digit counts a complete national number may have, narrowest first.
  List<int> get lengths => [for (final mask in masks) _slotsIn(mask)];

  /// Fewest digits a complete number here can have.
  int get minDigits => _slotsIn(masks.first);

  /// Most digits a number here can hold — the cap the field enforces.
  int get maxDigits => _slotsIn(masks.last);

  /// The narrowest mask [digits] still fits in, else the widest.
  ///
  /// This is what lets a variable-length plan work: an Australian number wears
  /// `#### ####` until the ninth digit arrives and it becomes `# #### ####`.
  String maskFor(String digits) {
    for (final mask in masks) {
      if (digits.length <= _slotsIn(mask)) return mask;
    }
    return masks.last;
  }

  /// [digits] punctuated by the mask it fits; anything past [maxDigits] is
  /// dropped. Separators are only written while a digit still needs a slot, so
  /// a half-typed number never ends on a dangling bracket or space.
  String format(String digits) {
    final numeric = _digitsOnly(digits);
    final mask = maskFor(numeric);
    final buffer = StringBuffer();
    var next = 0;
    for (var i = 0; i < mask.length && next < numeric.length; i++) {
      buffer.write(mask[i] == _slot ? numeric[next++] : mask[i]);
    }
    return buffer.toString();
  }

  /// Whether [digits] is a *complete* national number here.
  ///
  /// The length has to match one of the plan's shapes exactly rather than fall
  /// in a range, which is why Armenia accepts 8 or 10 digits but not the 9 in
  /// between.
  bool accepts(String digits) => lengths.contains(_digitsOnly(digits).length);

  /// The E.164 form of [digits]: `+351912345678`. What you send to an API, and
  /// what [AppCountries.split] reads back.
  String e164(String digits) => '+$dial${_digitsOnly(digits)}';

  /// How well this country answers [query] — lower is a better match, and a
  /// negative result means none at all. A leading `+` is ignored, so `+351`,
  /// `351`, `PT` and `portu` all find Portugal.
  ///
  /// Ranked rather than boolean because country names contain each other's
  /// codes: a plain `contains` puts Egypt above Portugal for the query `PT`,
  /// which is not what anyone typing two letters meant.
  int matchRank(String query) {
    final needle = query.trim().toLowerCase();
    if (needle.isEmpty) return 0;
    final bare = needle.startsWith('+') ? needle.substring(1) : needle;
    final lowerIso = iso.toLowerCase();
    final lowerName = name.toLowerCase();

    if (lowerIso == needle) return 0;
    if (dial == bare) return 1;
    if (lowerName.startsWith(needle)) return 2;
    if (lowerIso.startsWith(needle)) return 3;
    if (dial.startsWith(bare)) return 4;
    if (lowerName.contains(needle)) return 5;
    return -1;
  }

  /// Whether [query] matches this country at all — see [matchRank].
  bool matches(String query) => matchRank(query) >= 0;

  @override
  bool operator ==(Object other) =>
      identical(this, other) || (other is AppCountry && other.iso == iso);

  @override
  int get hashCode => iso.hashCode;

  @override
  String toString() => '$flag $name ($dialCode)';
}

/// A phone number as the field currently holds it — reported by
/// `AppPhoneInput.onChanged` so a form never has to re-parse the text.
@immutable
class AppPhoneNumber {
  /// Creates a number in [country] made of [national] digits.
  const AppPhoneNumber({required this.country, required this.national});

  /// The country the field is set to.
  final AppCountry country;

  /// The national part, digits only and unpunctuated: `912345678`.
  final String national;

  /// The full international form: `+351912345678`.
  String get e164 => country.e164(national);

  /// The national part wearing its mask: `912 345 678`.
  String get formatted => country.format(national);

  /// Whether this is a complete number for [country] — see [AppCountry.accepts].
  bool get isValid => national.isNotEmpty && country.accepts(national);

  /// Whether the user has typed nothing at all.
  bool get isEmpty => national.isEmpty;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      (other is AppPhoneNumber &&
          other.country == country &&
          other.national == national);

  @override
  int get hashCode => Object.hash(country, national);

  @override
  String toString() => e164;
}

/// The shipped country table and the lookups over it.
///
/// Numbering plans come from `flutter_multi_formatter` (MIT), reshaped so the
/// calling code sits outside the mask. They are a good description of how
/// numbers are *written*, not a substitute for libphonenumber — if you need
/// carrier-level correctness, validate server-side too.
abstract final class AppCountries {
  /// The country a field starts on when it is given nothing else.
  ///
  /// Assign at startup to follow the SIM, the locale, or wherever your users
  /// actually are: `AppCountries.initial = AppCountries.byIso('PT')!;`
  static AppCountry initial = byIso('US')!;

  /// Which country a *shared* calling code resolves to.
  ///
  /// Ten codes cover more than one territory — `+1` is both the US and Canada,
  /// `+7` both Russia and Kazakhstan. [byDialCode] has to answer with one of
  /// them, so the choice is written down here rather than left to table order.
  /// Edit freely; an unlisted code falls back to the first match by name.
  static const Map<String, String> preferredForSharedDialCode = {
    '1': 'US',
    '7': 'RU',
    '44': 'GB',
    '47': 'NO',
    '61': 'AU',
    '64': 'NZ',
    '262': 'RE',
    '354': 'IS',
    '500': 'FK',
    '590': 'GP',
  };

  /// Look up by ISO 3166-1 alpha-2, case-insensitive. Null when unknown.
  static AppCountry? byIso(String iso) => _byIso[iso.trim().toUpperCase()];

  /// Every country using [dial], with or without its `+`.
  static List<AppCountry> allByDialCode(String dial) {
    final code = _digitsOnly(dial);
    return [for (final country in all) if (country.dial == code) country];
  }

  /// The country a `+…` number belongs to, matched on the longest calling code
  /// that prefixes it — so `+1284…` resolves to the British Virgin Islands
  /// rather than to the United States. Shared codes resolve through
  /// [preferredForSharedDialCode]. Null when nothing matches.
  static AppCountry? byDialCode(String phone) {
    final digits = _digitsOnly(phone);
    if (digits.isEmpty) return null;

    final longest = digits.length < _longestDial ? digits.length : _longestDial;
    for (var length = longest; length > 0; length--) {
      final matches = allByDialCode(digits.substring(0, length));
      if (matches.isEmpty) continue;
      if (matches.length == 1) return matches.first;

      final preferred = preferredForSharedDialCode[matches.first.dial];
      return matches.firstWhere(
        (country) => country.iso == preferred,
        orElse: () => matches.first,
      );
    }
    return null;
  }

  /// Splits a number into the country it belongs to and its national digits.
  ///
  /// A `+`-prefixed number is resolved through [byDialCode]; anything else is
  /// treated as already national and paired with [fallback] — which is how a
  /// field seeded with a bare `912345678` keeps the country it is showing.
  ///
  ///   AppCountries.split('+351912345678')  // (Portugal, '912345678')
  static AppPhoneNumber split(String phone, {AppCountry? fallback}) {
    final country = fallback ?? initial;
    final trimmed = phone.trim();
    if (!trimmed.startsWith('+')) {
      return AppPhoneNumber(country: country, national: _digitsOnly(trimmed));
    }

    final match = byDialCode(trimmed);
    if (match == null) {
      return AppPhoneNumber(country: country, national: _digitsOnly(trimmed));
    }
    return AppPhoneNumber(
      country: match,
      national: _digitsOnly(trimmed).substring(match.dial.length),
    );
  }

  /// Countries matching [query], best match first — see [AppCountry.matchRank].
  /// An empty query returns everything, untouched.
  ///
  /// Pass [within] to search a subset, such as the countries one form offers.
  static List<AppCountry> search(String query, {List<AppCountry>? within}) {
    final pool = within ?? all;
    final ranked = <({int rank, int index, AppCountry country})>[];
    for (var index = 0; index < pool.length; index++) {
      final rank = pool[index].matchRank(query);
      if (rank >= 0) {
        ranked.add((rank: rank, index: index, country: pool[index]));
      }
    }
    // Ties keep the order they came in, which is alphabetical for the table.
    ranked.sort(
      (a, b) =>
          a.rank != b.rank ? a.rank.compareTo(b.rank) : a.index.compareTo(b.index),
    );
    return [for (final entry in ranked) entry.country];
  }

