import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

import '../../../core/constants/app_constants.dart';
import '../../../core/utils/extensions.dart';

/// Color role of [AppIconButton]. Mirrors [AppButtonVariant] and
/// [AppLeadingIconVariant] so every control speaks the same color vocabulary.
enum AppIconButtonVariant { primary, secondary, tertiary, danger }

/// Fill treatment of [AppIconButton] — how the variant color is applied.
///
/// - [filled]: solid variant background, contrasting icon.
/// - [tonal]: soft variant-tinted background, variant-colored icon.
/// - [outlined]: transparent background, variant-colored border + icon.
/// - [ghost]: no container at all — just the variant-colored icon.
enum AppIconButtonType { filled, tonal, outlined, ghost }

/// Corner shape of the tap target.
enum AppIconButtonShape { rounded, circle }

enum AppIconButtonSize { small, medium, large }

typedef _IconButtonSizeConfig = ({double container, double icon});

/// A tappable icon — [AppLeadingIcon]'s interactive sibling. Same color
/// vocabulary, but with a ripple, haptics, a loading state and a real touch
/// target. Use [AppLeadingIcon] when the icon is decoration, this when it does
/// something.
class AppIconButton extends StatelessWidget {
  const AppIconButton({
    super.key,
    required this.icon,
    this.onPressed,
    this.variant = AppIconButtonVariant.primary,
    this.type = AppIconButtonType.ghost,
    this.shape = AppIconButtonShape.circle,
    this.size = AppIconButtonSize.medium,
    this.tooltip,
    this.isLoading = false,
    this.color,
  });

  final IconData icon;

  /// Tap handler. Pass null to render the button in its disabled state.
  final VoidCallback? onPressed;
  final AppIconButtonVariant variant;
  final AppIconButtonType type;
  final AppIconButtonShape shape;
  final AppIconButtonSize size;

  /// Long-press label. Worth setting on every icon button — an icon on its own
  /// rarely names itself, and screen readers have nothing else to read.
  final String? tooltip;

  /// Replaces the icon with a spinner and ignores taps, keeping the same size
  /// so the surrounding layout doesn't jump.
  final bool isLoading;

  /// Overrides [variant]'s accent color. For the control that has to match a
  /// color the variant vocabulary doesn't name — a status tint, say. Reach for
  /// a [variant] first; this is the escape hatch.
  final Color? color;

  static const double _tonalFillOpacity = 0.12;
  static const double _outlinedBorderWidth = 1.5;
  static const double _disabledOpacity = 0.38;

  /// The tap target's outer dimension for [size]. Public so a layout that has
  /// to reserve room for the button — an AppBar's leading slot, say — can size
  /// that slot instead of guessing at it.
  static double dimensionOf(AppIconButtonSize size) => switch (size) {
        AppIconButtonSize.small => 32.0,
        AppIconButtonSize.medium => AppConstants.touchTarget,
        AppIconButtonSize.large => AppConstants.touchTarget + 16,
      };

  _IconButtonSizeConfig _sizeConfig() => (
        container: dimensionOf(size),
        icon: switch (size) {
          AppIconButtonSize.small => AppConstants.iconSmall,
          AppIconButtonSize.medium => AppConstants.iconMedium,
          AppIconButtonSize.large => AppConstants.iconLarge,
        },
      );

  /// The accent color, plus the color that reads on top of it.
  (Color, Color) _colorsOf(ThemeData theme) {
    final override = color;
    if (override != null) {
      // No colorScheme pair exists for an arbitrary color, so pick whichever
      // of black/white keeps the filled treatment legible.
      return (
        override,
        ThemeData.estimateBrightnessForColor(override) == Brightness.dark
            ? Colors.white
            : Colors.black,
      );
    }
    return switch (variant) {
      AppIconButtonVariant.primary => (
          theme.colorScheme.primary,
          theme.colorScheme.onPrimary,
        ),
      AppIconButtonVariant.secondary => (
          theme.colorScheme.secondary,
          theme.colorScheme.onSecondary,
        ),
      AppIconButtonVariant.tertiary => (
          theme.colorScheme.tertiary,
          theme.colorScheme.onTertiary,
        ),
      AppIconButtonVariant.danger => (
          theme.colorScheme.error,
          theme.colorScheme.onError,
        ),
    };
  }

  @override
  Widget build(BuildContext context) {
    final theme = context.theme;
    final sizeConfig = _sizeConfig();
    final (accent, onAccent) = _colorsOf(theme);
    final enabled = onPressed != null && !isLoading;

    // Variant chooses the color; type only decides how that color is applied.
    final (backgroundColor, foregroundColor) = switch (type) {
      AppIconButtonType.filled => (accent, onAccent),
      AppIconButtonType.tonal => (
          Color.alphaBlend(
            accent.withValues(alpha: _tonalFillOpacity),
            theme.colorScheme.surface,
          ),
          accent,
        ),
      AppIconButtonType.outlined || AppIconButtonType.ghost => (
          Colors.transparent,
          accent,
        ),
    };

    // A disabled button stays its variant, just faded — never a generic grey.
    final resolvedForeground = enabled
        ? foregroundColor
        : foregroundColor.withValues(alpha: _disabledOpacity);
    final resolvedBackground = enabled
        ? backgroundColor
        : backgroundColor.withValues(alpha: _disabledOpacity);

    final border = type == AppIconButtonType.outlined
        ? BorderSide(color: resolvedForeground, width: _outlinedBorderWidth)
        : BorderSide.none;

    final button = Material(
      color: resolvedBackground,
      clipBehavior: Clip.antiAlias,
      shape: shape == AppIconButtonShape.circle
          ? CircleBorder(side: border)
          : RoundedRectangleBorder(
              borderRadius: AppConstants.borderRadius12,
              side: border,
            ),
      child: InkWell(
        onTap: enabled
            ? () {
                HapticFeedback.selectionClick();
                onPressed!();
              }
            : null,
        child: SizedBox.square(
          dimension: sizeConfig.container,
          child: isLoading
              ? Center(
                  child: SizedBox.square(
                    dimension: sizeConfig.icon,
                    child: CircularProgressIndicator(
                      strokeWidth: 2,
                      color: resolvedForeground,
                    ),
                  ),
                )
              : Icon(icon, size: sizeConfig.icon, color: resolvedForeground),
        ),
      ),
    );

    if (tooltip == null) return button;
    return Tooltip(message: tooltip!, child: button);
  }
}

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

import '../../../core/constants/app_constants.dart';
import '../../../core/utils/extensions.dart';

/// Fill treatment of the sheet's close button.
///
/// Mirrors `AppIconButtonType`'s naming so it reads like the rest of the kit.
/// It is redeclared here rather than imported because this widget ships with
/// `moarch init` and AppIconButton does not — an init widget can only lean on
/// other init widgets.
enum AppSheetCloseType { filled, tonal, outlined, ghost }

/// The standard inside of a bottom sheet: a rounded surface panel with a drag
/// handle (grabber) at the top, an optional [title], an optional close button,
/// and your [child].
/// Pass this as the `child` to `AppBottomModals.showAppBottomModal`.
class AppBottomSheetScaffold extends StatelessWidget {
  const AppBottomSheetScaffold({
    super.key,
    required this.child,
    this.title,
    this.showHandle = true,
    this.padding = AppConstants.paddingPage,
    this.titleAlign = TextAlign.center,
    this.handleWidth = 40,
    this.handleHeight = 4,
    this.handleColor,
    this.showClose = false,
    this.onClose,
    this.closeIcon = Icons.close,
    this.closeType = AppSheetCloseType.tonal,
    this.closeColor,
  });

  final Widget child;
  final String? title;
  final bool showHandle;
  final EdgeInsetsGeometry padding;

  /// Centered reads as a modal, [TextAlign.start] as a panel. Pick one per app
  /// and keep to it.
  final TextAlign titleAlign;

  final double handleWidth;
  final double handleHeight;

  /// Defaults to a muted `onSurfaceVariant`. Worth overriding only when the
  /// sheet sits on a colored surface.
  final Color? handleColor;

  /// Shows a close button in the sheet's top corner. The drag handle already
  /// says "dismissable" — add this when the sheet is tall enough that the
  /// handle scrolls out of reach, or when dismissal needs to be obvious.
  final bool showClose;

  /// Overrides the default `Navigator.maybePop` — e.g. to confirm unsaved work.
  final VoidCallback? onClose;

  final IconData closeIcon;

  /// How the close button wears [closeColor]. Tonal gives the soft grey circle
  /// most sheets want; [AppSheetCloseType.ghost] is a bare glyph.
  final AppSheetCloseType closeType;

  /// Defaults to `onSurfaceVariant` — a close button is chrome, not an action,
  /// so it stays neutral unless you say otherwise.
  final Color? closeColor;

  /// Matches AppIconButton's `small` tap target, so a sheet close and an icon
  /// button elsewhere in the app are the same size.
  static const double _closeDimension = 32;
  static const double _closeTonalOpacity = 0.12;
  static const double _closeBorderWidth = 1.5;
  static const double _handleOpacity = 0.4;

  Widget _buildClose(BuildContext context, ThemeData theme) {
    final accent = closeColor ?? theme.colorScheme.onSurfaceVariant;
    final (background, foreground) = switch (closeType) {
      AppSheetCloseType.filled => (accent, theme.colorScheme.surface),
      AppSheetCloseType.tonal => (
          Color.alphaBlend(
            accent.withValues(alpha: _closeTonalOpacity),
            theme.colorScheme.surface,
          ),
          accent,
        ),
      AppSheetCloseType.outlined || AppSheetCloseType.ghost => (
          Colors.transparent,
          accent,
        ),
    };

    return Tooltip(
      message: MaterialLocalizations.of(context).closeButtonTooltip,
      child: Material(
        color: background,
        clipBehavior: Clip.antiAlias,
        shape: CircleBorder(
          side: closeType == AppSheetCloseType.outlined
              ? BorderSide(color: accent, width: _closeBorderWidth)
              : BorderSide.none,
        ),
        child: InkWell(
          onTap: () {
            HapticFeedback.selectionClick();
            if (onClose != null) {
              onClose!();
            } else {
              Navigator.maybePop(context);
            }
          },
          child: SizedBox.square(
            dimension: _closeDimension,
            child: Icon(
              closeIcon,
              size: AppConstants.iconSmall,
              color: foreground,
            ),
          ),
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final theme = context.theme;
    return Container(
      decoration: BoxDecoration(
        color: theme.colorScheme.surface,
        borderRadius: const BorderRadius.vertical(
          top: Radius.circular(AppConstants.radius24),
        ),
      ),
      child: SafeArea(
        top: false,
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            if (showHandle)
              Center(
                child: Container(
                  margin: const EdgeInsets.only(top: AppConstants.space12),
                  width: handleWidth,
                  height: handleHeight,
                  decoration: BoxDecoration(
                    color: handleColor ??
                        theme.colorScheme.onSurfaceVariant
                            .withValues(alpha: _handleOpacity),
                    borderRadius: AppConstants.borderRadiusFull,
                  ),
                ),
              ),
            Padding(
              padding: padding,
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  if (title != null || showClose) ...[
                    // A Stack rather than a Row: it keeps a centered title
                    // centered on the sheet instead of on the space left over
                    // beside the close button.
                    Stack(
                      alignment: AlignmentDirectional.centerEnd,
                      children: [
                        if (title != null)
                          Padding(
                            // Reserve the close button's width on both sides so
                            // a centered title doesn't drift left to avoid it.
                            padding: EdgeInsets.symmetric(
                              horizontal: showClose ? _closeDimension : 0,
                            ),
                            child: SizedBox(
                              width: double.infinity,
                              child: Text(
                                title!,
                                style: theme.textTheme.titleLarge,
                                textAlign: titleAlign,
                              ),
                            ),
                          ),
                        if (showClose) _buildClose(context, theme),
                      ],
                    ),
                    const SizedBox(height: AppConstants.space16),
                  ],
                  child,
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

import '../../../core/constants/app_constants.dart';
import '../../../core/utils/extensions.dart';
import '../buttons/app_icon_button.dart';
import '../indicators/app_tag.dart';

/// An inline status message — the calm, persistent counterpart to AppToast.
/// Use a banner for something that stays true while the screen is open
/// ("You're offline", "Verify your email"), and a toast for something that
/// just happened.
///
/// Colors come from [AppTagStatus], shared with [AppTag], so a banner and a
/// pill about the same thing read as the same thing.
class AppBanner extends StatelessWidget {
  const AppBanner({
    super.key,
    required this.message,
    this.title,
    this.status = AppTagStatus.info,
    this.icon,
    this.actionLabel,
    this.onAction,
    this.onDismiss,
    this.dismissIcon = Icons.close,
    this.dismissType = AppIconButtonType.ghost,
    this.dismissShape = AppIconButtonShape.circle,
  });

  final String message;

  /// Optional bold first line. Skip it for one-sentence banners.
  final String? title;
  final AppTagStatus status;

  /// Overrides the status's default icon.
  final IconData? icon;

  /// Inline text action — "Retry", "Verify now". Shown only when [onAction]
  /// is also set.
  final String? actionLabel;
  final VoidCallback? onAction;

  /// Shows a close button when set. Leave it null for a banner the user
  /// shouldn't be able to wave away.
  final VoidCallback? onDismiss;

  final IconData dismissIcon;

  /// How the dismiss button wears the [status] color. Ghost keeps the banner
  /// quiet; [AppIconButtonType.tonal] gives the close a soft container of its
  /// own, which helps when the banner is long enough to hunt for it.
  final AppIconButtonType dismissType;
  final AppIconButtonShape dismissShape;

  static const double _fillOpacity = 0.10;
  static const double _borderOpacity = 0.35;

  Color _colorOf(ThemeData theme) => switch (status) {
        AppTagStatus.neutral => theme.colorScheme.onSurfaceVariant,
        AppTagStatus.success => AppConstants.success,
        AppTagStatus.warning => AppConstants.warning,
        AppTagStatus.error => theme.colorScheme.error,
        AppTagStatus.info => AppConstants.info,
      };

  IconData _iconOf() => switch (status) {
        AppTagStatus.neutral => Icons.info_outline,
        AppTagStatus.success => Icons.check_circle_outline,
        AppTagStatus.warning => Icons.warning_amber_outlined,
        AppTagStatus.error => Icons.error_outline,
        AppTagStatus.info => Icons.info_outline,
      };

  @override
  Widget build(BuildContext context) {
    final theme = context.theme;
    final color = _colorOf(theme);

    return Container(
      padding: AppConstants.padding12,
      decoration: BoxDecoration(
        color: color.withValues(alpha: _fillOpacity),
        borderRadius: AppConstants.borderRadius12,
        border: Border.all(color: color.withValues(alpha: _borderOpacity)),
      ),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Icon(icon ?? _iconOf(), color: color, size: AppConstants.iconMedium),
          const SizedBox(width: AppConstants.space12),
          Expanded(
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                if (title != null) ...[
                  Text(
                    title!,
                    style: theme.textTheme.titleSmall?.copyWith(color: color),
                  ),
                  const SizedBox(height: 2),
                ],
                Text(
                  message,
                  style: theme.textTheme.bodyMedium?.copyWith(
                    color: theme.colorScheme.onSurface,
                  ),
                ),
                if (actionLabel != null && onAction != null) ...[
                  const SizedBox(height: AppConstants.space4),
                  // A bare text action keeps the banner quiet: it is
                  // information first, a call to action second.
                  TextButton(
                    onPressed: () {
                      HapticFeedback.selectionClick();
                      onAction!();
                    },
                    style: TextButton.styleFrom(
                      foregroundColor: color,
                      padding: EdgeInsets.zero,
                      minimumSize: Size.zero,
                      tapTargetSize: MaterialTapTargetSize.shrinkWrap,
                    ),
                    child: Text(actionLabel!),
                  ),
                ],
              ],
            ),
          ),
          if (onDismiss != null) ...[
            const SizedBox(width: AppConstants.space4),
            AppIconButton(
              icon: dismissIcon,
              onPressed: onDismiss,
              // The banner's color comes from AppTagStatus, which the variant
              // vocabulary doesn't name — hence the explicit override.
              color: color,
              type: dismissType,
              shape: dismissShape,
              size: AppIconButtonSize.small,
              tooltip: 'Dismiss',
            ),
          ],
        ],
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

import '../../../core/constants/app_constants.dart';
import '../../../core/utils/extensions.dart';
import './app_input_style.dart';

/// A quantity stepper — "− 2 +". For picking a small count, where a slider
/// would be imprecise and a text field is overkill.
///
/// The buttons disable themselves at [min] and [max], so the value can never
/// leave the range you allow.
class AppStepper extends StatelessWidget {
  const AppStepper({
    super.key,
    required this.value,
    required this.onChanged,
    this.min = 0,
    this.max = 99,
    this.step = 1,
    this.variant,
    this.size,
  });

  final int value;

  /// Pass null to render the whole stepper disabled.
  final ValueChanged<int>? onChanged;
  final int min;
  final int max;

  /// How much one tap moves the value.
  final int step;
  final AppInputVariant? variant;
  final AppInputSize? size;

  static const double _fillOpacity = 0.06;
  static const double _borderOpacity = 0.25;
  static const double _disabledOpacity = 0.35;

  @override
  Widget build(BuildContext context) {
    final theme = context.theme;
    final accent = AppInputStyle.accentOf(context, variant);
    final sizeConfig = AppInputStyle.configOf(size);
    final enabled = onChanged != null;

    void emit(int next) {
      HapticFeedback.selectionClick();
      onChanged!(next.clamp(min, max));
    }

    return Container(
      decoration: BoxDecoration(
        color: accent.withValues(alpha: _fillOpacity),
        borderRadius: AppConstants.borderRadiusFull,
        border: Border.all(color: accent.withValues(alpha: _borderOpacity)),
      ),
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          _StepButton(
            icon: Icons.remove,
            tooltip: 'Decrease',
            color: accent,
            iconSize: sizeConfig.iconSize,
            disabledOpacity: _disabledOpacity,
            onTap: enabled && value > min ? () => emit(value - step) : null,
          ),
          ConstrainedBox(
            constraints: const BoxConstraints(minWidth: AppConstants.space32),
            child: Text(
              '$value',
              textAlign: TextAlign.center,
              style: theme.textTheme.titleMedium?.copyWith(
                fontSize: sizeConfig.fontSize,
                color: enabled
                    ? theme.colorScheme.onSurface
                    : theme.colorScheme.onSurface
                        .withValues(alpha: _disabledOpacity),
              ),
            ),
          ),
          _StepButton(
            icon: Icons.add,
            tooltip: 'Increase',
            color: accent,
            iconSize: sizeConfig.iconSize,
            disabledOpacity: _disabledOpacity,
            onTap: enabled && value < max ? () => emit(value + step) : null,
          ),
        ],
      ),
    );
  }
}

class _StepButton extends StatelessWidget {
  const _StepButton({
    required this.icon,
    required this.tooltip,
    required this.color,
    required this.iconSize,
    required this.disabledOpacity,
    required this.onTap,
  });

  final IconData icon;

  /// Names the button. A bare glyph tells a screen reader nothing, and "−" and
  /// "+" are exactly the two a stepper cannot afford to have confused.
  final String tooltip;

  final Color color;
  final double iconSize;
  final double disabledOpacity;
  final VoidCallback? onTap;

  @override
  Widget build(BuildContext context) {
    return Tooltip(
      message: tooltip,
      child: Semantics(
        button: true,
        enabled: onTap != null,
        label: tooltip,
        child: InkWell(
          customBorder: const CircleBorder(),
          onTap: onTap,
          child: ConstrainedBox(
            // Material's minimum tap target. The glyph alone left it at 40.
            constraints: const BoxConstraints(
              minWidth: AppConstants.touchTarget,
              minHeight: AppConstants.touchTarget,
            ),
            child: Icon(
              icon,
              size: iconSize,
              color: onTap == null
                  ? color.withValues(alpha: disabledOpacity)
                  : color,
            ),
          ),
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

import '../inputs/app_input_style.dart';
import '../../../core/constants/app_constants.dart';
import '../../../core/utils/extensions.dart';

/// One tab in an [AppTabBar].
class AppTab {
  const AppTab({required this.label, this.icon});

  final String label;
  final IconData? icon;
}

/// How the current tab is marked.
///
/// - [underline]: a line under the selected label (Material's own).
/// - [pill]: the selected tab is filled with the accent, like [AppSegmented].
enum AppTabsStyle { underline, pill }

/// A [TabBar] wearing the kit's vocabulary, sized to sit in an app bar.
///
/// Being a [PreferredSizeWidget] is the point — it drops straight into the
/// `bottom` slot of [AppAppBar], which is where a tab bar belongs:
///
/// ```dart
/// DefaultTabController(
///   length: 2,
///   child: Scaffold(
///     appBar: AppAppBar(
///       title: 'Orders',
///       bottom: const AppTabBar(
///         tabs: [AppTab(label: 'Open'), AppTab(label: 'Closed')],
///       ),
///     ),
///     body: const TabBarView(children: [...]),
///   ),
/// )
/// ```
///
/// With no [controller] it reads the [DefaultTabController] above it, as
/// [TabBar] does. [AppTabs] is the version that owns a controller for you and
/// puts the views underneath.
class AppTabBar extends StatelessWidget implements PreferredSizeWidget {
  const AppTabBar({
    super.key,
    required this.tabs,
    this.controller,
    this.onTap,
    this.style = AppTabsStyle.underline,
    this.isScrollable = false,
    this.variant,
  });

  final List<AppTab> tabs;

  /// Null falls back to the [DefaultTabController] above this widget.
  final TabController? controller;

  /// Fires on a tap, not on a swipe between views — listen to the controller
  /// if you need both.
  final ValueChanged<int>? onTap;

  final AppTabsStyle style;

  /// Lets the row scroll instead of dividing the width evenly. What more than
  /// about four tabs needs, and what any tab with a long label needs.
  final bool isScrollable;

  /// Null follows [AppInputConfig.defaults].
  final AppInputVariant? variant;

  /// The [Tab] widgets, built once so the bar and [preferredSize] can never
  /// disagree about what is in it.
  List<Widget> get _tabWidgets => [
    for (final tab in tabs)
      Tab(text: tab.label, icon: tab.icon == null ? null : Icon(tab.icon)),
  ];

  /// Measured by asking a bare [TabBar] holding the same tabs, so a row with
  /// icons gets the taller bar Material specifies — and keeps getting the right
  /// answer if those metrics ever change.
  @override
  Size get preferredSize => TabBar(tabs: _tabWidgets).preferredSize;

  @override
  Widget build(BuildContext context) {
    final accent = AppInputStyle.accentOf(context, variant);
    final onAccent = AppInputStyle.onAccentOf(context, variant);
    final pill = style == AppTabsStyle.pill;

    return TabBar(
      controller: controller,
      isScrollable: isScrollable,
      tabs: _tabWidgets,
      onTap: onTap == null
          ? null
          : (index) {
              HapticFeedback.selectionClick();
              onTap!(index);
            },
      // A filled indicator has to cover the whole tab for the label to read on
      // top of it; an underline is drawn under the label only.
      indicatorSize: pill ? TabBarIndicatorSize.tab : TabBarIndicatorSize.label,
      indicator: pill
          ? BoxDecoration(
              color: accent,
              borderRadius: AppConstants.borderRadiusFull,
            )
          : null,
      indicatorColor: pill ? null : accent,
      // Ignored once `indicator` is set, but TabBar asserts it is positive
      // either way — so the pill branch cannot answer 0.
      indicatorWeight: AppInputStyle.config.focusedBorderWidth * 2,
      labelColor: pill ? onAccent : accent,
      unselectedLabelColor: context.colorScheme.onSurfaceVariant,
      labelStyle: context.textTheme.titleSmall?.copyWith(
        fontWeight: FontWeight.bold,
      ),
      unselectedLabelStyle: context.textTheme.titleSmall,
      // The pill carries its own edge; Material's divider under the row only
      // makes sense beneath an underline.
      dividerColor: pill ? Colors.transparent : null,
      splashBorderRadius: AppConstants.borderRadiusFull,
    );
  }
}

/// An [AppTabBar] with its views under it, owning the [TabController].
///
/// The bar-plus-views pairing is most of what a tab bar is used for, and doing
/// it by hand means a [StatefulWidget], a ticker and a `dispose` every time:
///
/// ```dart
/// AppTabs(
///   tabs: const [AppTab(label: 'Open'), AppTab(label: 'Closed')],
///   children: [OpenOrders(), ClosedOrders()],
/// )
/// ```
///
/// It fills the height it is given, so put it in a [Column] under an
/// [Expanded], or hand it a body's worth of space directly. When the tab bar
/// belongs in the app bar instead, use [AppTabBar] with a
/// [DefaultTabController].
class AppTabs extends StatefulWidget {
  const AppTabs({
    super.key,
    required this.tabs,
    required this.children,
    this.initialIndex = 0,
    this.onChanged,
    this.style = AppTabsStyle.underline,
    this.isScrollable = false,
    this.variant,
    this.padding,
  });

  final List<AppTab> tabs;

  /// One view per tab — a different count is a bug, not a layout to guess at.
  final List<Widget> children;

  final int initialIndex;

  /// Fires for a tap *and* for a swipe, once the move has settled.
  final ValueChanged<int>? onChanged;

  final AppTabsStyle style;
  final bool isScrollable;

  /// Null follows [AppInputConfig.defaults].
  final AppInputVariant? variant;

  /// Inset around the bar. Null is none — the bar spans the full width, as it
  /// does in an app bar.
  final EdgeInsetsGeometry? padding;

  @override
  State<AppTabs> createState() => _AppTabsState();
}

class _AppTabsState extends State<AppTabs> with TickerProviderStateMixin {
  late TabController _controller;

  /// What [AppTabs.onChanged] last reported, so a settled swipe fires once
  /// rather than on every frame of the animation.
  late int _reportedIndex;

  @override
  void initState() {
    super.initState();
    assert(widget.tabs.isNotEmpty, 'AppTabs: needs at least one tab.');
    _reportedIndex = widget.initialIndex;
    _controller = _createController();
  }

  @override
  void didUpdateWidget(AppTabs oldWidget) {
    super.didUpdateWidget(oldWidget);
    // A TabController's length is fixed, so a tab list that grew or shrank
    // needs a new one — otherwise the bar asserts on the next build.
    if (widget.tabs.length != oldWidget.tabs.length) {
      final previous = _controller;
      _controller = _createController(
        index: previous.index.clamp(0, widget.tabs.length - 1),
      );
      previous
        ..removeListener(_onControllerChanged)
        ..dispose();
    }
  }

  TabController _createController({int? index}) {
    return TabController(
      length: widget.tabs.length,
      initialIndex: index ?? widget.initialIndex.clamp(0, widget.tabs.length - 1),
      vsync: this,
    )..addListener(_onControllerChanged);
  }

  /// Reports the tab the user landed on. `indexIsChanging` is still true while
  /// a tap animates, and the index is already the destination — so waiting for
  /// it to clear reports the move once, whether it came from a tap or a swipe.
  void _onControllerChanged() {
    if (_controller.indexIsChanging) return;
    if (_controller.index == _reportedIndex) return;
    _reportedIndex = _controller.index;
    widget.onChanged?.call(_controller.index);
  }

  @override
  void dispose() {
    _controller
      ..removeListener(_onControllerChanged)
      ..dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    assert(
      widget.tabs.length == widget.children.length,
      'AppTabs: ${widget.tabs.length} tabs but ${widget.children.length} '
      'children — every tab needs exactly one view.',
    );

    final bar = AppTabBar(
      tabs: widget.tabs,
      controller: _controller,
      style: widget.style,
      isScrollable: widget.isScrollable,
      variant: widget.variant,
    );

    return Column(
      children: [
        widget.padding == null
            ? bar
            : Padding(padding: widget.padding!, child: bar),
        Expanded(
          child: TabBarView(controller: _controller, children: widget.children),
        ),
      ],
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

import '../inputs/app_input_style.dart';
import '../../../core/constants/app_constants.dart';
import '../../../core/utils/extensions.dart';

/// Where one [AppTimelineEntry] stands in the sequence — which is what its node
/// is drawn from.
///
/// - [done]: behind us. A filled node.
/// - [current]: where the thing is now. A ringed node, drawing the eye.
/// - [pending]: still to come. A hollow, dimmed node.
/// - [failed]: went wrong here. Error-colored, whatever the variant.
enum AppTimelineStatus { done, current, pending, failed }

/// One event on an [AppTimeline].
class AppTimelineEntry {
  const AppTimelineEntry({
    required this.title,
    this.subtitle,
    this.timestamp,
    this.status = AppTimelineStatus.done,
    this.icon,
    this.trailing,
    this.onTap,
  });

  final String title;
  final String? subtitle;

  /// Shown under the subtitle, dimmed — "2 hours ago", "14:32", a date. Already
  /// formatted: the timeline does not decide how an app writes its times.
  final String? timestamp;

  final AppTimelineStatus status;

  /// Drawn inside the node instead of a dot — a check, a truck, a warning.
  final IconData? icon;

  final Widget? trailing;
  final VoidCallback? onTap;
}

/// A vertical sequence of events, each on a node joined to the next by a line —
/// an order's progress, an audit trail, a delivery status.
///
/// ```dart
/// AppTimeline(
///   entries: [
///     AppTimelineEntry(title: 'Ordered', timestamp: 'Mon 09:12'),
///     AppTimelineEntry(title: 'Shipped', timestamp: 'Tue 11:40'),
///     AppTimelineEntry(
///       title: 'Out for delivery',
///       status: AppTimelineStatus.current,
///     ),
///     AppTimelineEntry(title: 'Delivered', status: AppTimelineStatus.pending),
///   ],
/// )
/// ```
///
/// It sizes to its content, so it drops into a [Column] or an
/// [AppSingleScrollView] without a height. For a list long enough to need lazy
/// rows, [entryBuilder] gives you one row you can put in a `ListView.builder`.
class AppTimeline extends StatelessWidget {
  const AppTimeline({
    super.key,
    required this.entries,
    this.variant,
    this.nodeSize = 16,
    this.padding,
  });

  final List<AppTimelineEntry> entries;

  /// Null follows [AppInputConfig.defaults].
  final AppInputVariant? variant;

  /// Diameter of a node. The connector's width and the gap to the text follow
  /// it, so one number scales the rail.
  final double nodeSize;

  final EdgeInsetsGeometry? padding;

  /// One row, for a caller building its own lazy list:
  ///
  /// ```dart
  /// ListView.builder(
  ///   itemCount: entries.length,
  ///   itemBuilder: (context, i) => AppTimeline.entryBuilder(
  ///     entries[i],
  ///     isLast: i == entries.length - 1,
  ///   ),
  /// )
  /// ```
  static Widget entryBuilder(
    AppTimelineEntry entry, {
    required bool isLast,
    AppInputVariant? variant,
    double nodeSize = 16,
  }) => _TimelineRow(
    entry: entry,
    isLast: isLast,
    variant: variant,
    nodeSize: nodeSize,
  );

  @override
  Widget build(BuildContext context) {
    final column = Column(
      mainAxisSize: MainAxisSize.min,
      children: [
        for (var i = 0; i < entries.length; i++)
          _TimelineRow(
            entry: entries[i],
            // The last node has nothing to join, and a line running off the
            // bottom of a finished sequence reads as a missing step.
            isLast: i == entries.length - 1,
            variant: variant,
            nodeSize: nodeSize,
          ),
      ],
    );

    return padding == null ? column : Padding(padding: padding!, child: column);
  }
}

class _TimelineRow extends StatelessWidget {
  const _TimelineRow({
    required this.entry,
    required this.isLast,
    required this.nodeSize,
    this.variant,
  });

  final AppTimelineEntry entry;
  final bool isLast;
  final double nodeSize;
  final AppInputVariant? variant;

  /// The node's color: the variant for everything that has happened or is
  /// happening, the theme's error for a step that failed, and a faded variant
  /// for one that has not been reached.
  Color _colorOf(BuildContext context) {
    final accent = AppInputStyle.accentOf(context, variant);
    return switch (entry.status) {
      AppTimelineStatus.failed => context.colorScheme.error,
      AppTimelineStatus.pending => accent.withValues(
        alpha: AppInputStyle.config.idleBorderOpacity,
      ),
      _ => accent,
    };
  }

  @override
  Widget build(BuildContext context) {
    final color = _colorOf(context);
    final content = _content(context);

    return IntrinsicHeight(
      child: Row(
        // Stretch is what lets the connector fill the row: without it the rail
        // column is only as tall as its dot, and the line never reaches the
        // next node.
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          SizedBox(
            width: nodeSize * 2,
            child: Column(
              children: [
                _node(color),
                if (!isLast)
                  Expanded(
                    child: Container(
                      width: nodeSize / 8,
                      margin: const EdgeInsets.symmetric(
                        vertical: AppConstants.space4,
                      ),
                      color: color.withValues(alpha: 0.4),
                    ),
                  ),
              ],
            ),
          ),
          Expanded(
            child: Padding(
              padding: EdgeInsets.only(
                left: AppConstants.space4,
                bottom: isLast ? 0 : AppConstants.space16,
              ),
              child: entry.onTap == null
                  ? content
                  : InkWell(
                      onTap: () {
                        HapticFeedback.selectionClick();
                        entry.onTap!();
                      },
                      borderRadius: AppConstants.borderRadius8,
                      child: content,
                    ),
            ),
          ),
        ],
      ),
    );
  }

  Widget _node(Color color) {
    final hollow = entry.status == AppTimelineStatus.pending;
    final ringed = entry.status == AppTimelineStatus.current;
    final icon = entry.icon;

    return Container(
      // Centers the dot on the first line of the title rather than on the row,
      // which is what makes a two-line entry still look joined up.
      margin: const EdgeInsets.only(top: AppConstants.space4),
      width: nodeSize,
      height: nodeSize,
      decoration: BoxDecoration(
        shape: BoxShape.circle,
        color: hollow ? Colors.transparent : color,
        border: Border.all(
          color: color,
          width: ringed ? nodeSize / 4 : nodeSize / 8,
        ),
      ),
      child: icon == null
          ? null
          : FittedBox(
              fit: BoxFit.scaleDown,
              child: Icon(icon, color: hollow ? color : Colors.white),
            ),
    );
  }

  Widget _content(BuildContext context) {
    final subtitle = entry.subtitle;
    final timestamp = entry.timestamp;
    final trailing = entry.trailing;
    final dimmed = entry.status == AppTimelineStatus.pending;

    return Row(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Expanded(
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(
                entry.title,
                style: context.textTheme.bodyLarge?.copyWith(
                  fontWeight: entry.status == AppTimelineStatus.current
                      ? FontWeight.bold
                      : FontWeight.w500,
                  color: dimmed ? context.colorScheme.onSurfaceVariant : null,
                ),
              ),
              if (subtitle != null)
                Text(
                  subtitle,
                  style: context.textTheme.bodyMedium?.copyWith(
                    color: context.colorScheme.onSurfaceVariant,
                  ),
                ),
              if (timestamp != null)
                Padding(
                  padding: const EdgeInsets.only(top: AppConstants.space4),
                  child: Text(
                    timestamp,
                    style: context.textTheme.bodySmall?.copyWith(
                      color: context.colorScheme.onSurfaceVariant,
                    ),
                  ),
                ),
            ],
          ),
        ),
        // An empty box rather than a null-aware element: this file has to
        // compile in a project whose pubspec still asks for an older Dart.
        trailing ?? const SizedBox.shrink(),
      ],
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

import './app_bottom_nav.dart';
import '../inputs/app_input_style.dart';
import '../../../core/constants/app_constants.dart';
import '../../../core/utils/extensions.dart';

/// The side menu, reading the same [AppNavDestination] list as [AppBottomNav]
/// so a phone and a tablet describe their navigation once.
///
/// ```dart
/// Scaffold(
///   drawer: AppDrawer(
///     destinations: destinations,
///     selectedIndex: index,
///     onDestinationSelected: _go,
///     header: const AppDrawerHeader(title: 'Acme', subtitle: 'Signed in'),
///   ),
///   ...
/// )
/// ```
///
/// It closes itself after a pick. A drawer that stays open over the screen it
/// just navigated to is the most common way this widget is got wrong, and there
/// is no case where a modal drawer should survive its own selection.
class AppDrawer extends StatelessWidget {
  const AppDrawer({
    super.key,
    required this.destinations,
    required this.selectedIndex,
    required this.onDestinationSelected,
    this.header,
    this.footer,
    this.variant,
  });

  final List<AppNavDestination> destinations;
  final int selectedIndex;
  final ValueChanged<int> onDestinationSelected;

  /// Shown above the destinations — an [AppDrawerHeader], a logo, an account
  /// row. It is not a destination and does not shift the selected index.
  final Widget? header;

  /// Shown under the destinations — a sign-out row, a version string.
  final Widget? footer;

  /// Null follows [AppInputConfig.defaults].
  final AppInputVariant? variant;

  /// Closes the drawer if this one is open as a drawer at all — on a wide
  /// layout the same widget may be pinned beside the content, where there is
  /// nothing to close.
  void _dismiss(BuildContext context) {
    final scaffold = Scaffold.maybeOf(context);
    if (scaffold == null) return;
    if (scaffold.isDrawerOpen) {
      scaffold.closeDrawer();
    } else if (scaffold.isEndDrawerOpen) {
      scaffold.closeEndDrawer();
    }
  }

  @override
  Widget build(BuildContext context) {
    final accent = AppInputStyle.accentOf(context, variant);

    return NavigationDrawer(
      selectedIndex: selectedIndex,
      backgroundColor: context.colorScheme.surface,
      indicatorColor: accent.withValues(alpha: AppInputStyle.config.fillOpacity * 2),
      indicatorShape: RoundedRectangleBorder(
        borderRadius: AppConstants.borderRadiusFull,
      ),
      onDestinationSelected: (index) {
        HapticFeedback.selectionClick();
        _dismiss(context);
        onDestinationSelected(index);
      },
      children: [
        // NavigationDrawer counts only its NavigationDrawerDestination
        // children, so a header, a divider or a footer can sit among them
        // without throwing the selected index off.
        //
        // An empty box rather than a null-aware element: this file has to
        // compile in a project whose pubspec still asks for an older Dart.
        header ?? const SizedBox.shrink(),
        for (final destination in destinations)
          NavigationDrawerDestination(
            icon: Icon(destination.icon),
            selectedIcon: Icon(destination.selectedIcon, color: accent),
            label: Text(destination.label),
          ),
        if (footer != null) ...[
          const Padding(
            padding: AppConstants.paddingV8,
            child: Divider(height: 1),
          ),
          footer!,
        ],
      ],
    );
  }
}

/// A title-and-subtitle block for the top of an [AppDrawer]. Pass anything else
/// you like as [AppDrawer.header] — this is only the common case.
class AppDrawerHeader extends StatelessWidget {
  const AppDrawerHeader({
    super.key,
    required this.title,
    this.subtitle,
    this.leading,
  });

  final String title;
  final String? subtitle;
  final Widget? leading;

  @override
  Widget build(BuildContext context) {
    return Padding(
      // Clears the status bar without a SafeArea: the drawer starts at the top
      // of the screen, and NavigationDrawer does not inset its children.
      padding: EdgeInsets.only(
        top: MediaQuery.paddingOf(context).top + AppConstants.space16,
        left: AppConstants.space24,
        right: AppConstants.space16,
        bottom: AppConstants.space16,
      ),
      child: Row(
        children: [
          // The gap travels with the leading widget, so a header without one
          // does not start with 12px of nothing.
          if (leading != null) ...[
            leading!,
            const SizedBox(width: AppConstants.space12),
          ],
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  title,
                  style: context.textTheme.titleMedium?.copyWith(
                    fontWeight: FontWeight.bold,
                  ),
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                ),
                if (subtitle != null)
                  Text(
                    subtitle!,
                    style: context.textTheme.bodySmall?.copyWith(
                      color: context.colorScheme.onSurfaceVariant,
                    ),
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                  ),
              ],
            ),
          ),
        ],
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

import './app_bottom_nav.dart';
import '../inputs/app_input_style.dart';
import '../../../core/utils/extensions.dart';

/// The vertical navigation a wide screen shows instead of a bottom bar, reading
/// the same [AppNavDestination] list as [AppBottomNav].
///
/// A bottom bar on a tablet puts the app's navigation as far from the hand as
/// the layout allows, which is why Material asks for a rail past 600dp.
/// [AppAdaptiveNav] makes that switch for you.
class AppNavRail extends StatelessWidget {
  const AppNavRail({
    super.key,
    required this.destinations,
    required this.index,
    required this.onDestinationSelected,
    this.extended = false,
    this.leading,
    this.trailing,
    this.variant,
  });

  final List<AppNavDestination> destinations;
  final int index;
  final ValueChanged<int> onDestinationSelected;

  /// Shows the labels beside the icons rather than under them — for a window
  /// wide enough that a narrow rail would be wasting the space.
  final bool extended;

  /// Above the destinations: a logo, or the [FloatingActionButton] a rail is
  /// expected to host.
  final Widget? leading;

  /// Below the destinations, pushed to the bottom of the rail.
  final Widget? trailing;

  /// Null follows [AppInputConfig.defaults].
  final AppInputVariant? variant;

  @override
  Widget build(BuildContext context) {
    final accent = AppInputStyle.accentOf(context, variant);

    return NavigationRail(
      selectedIndex: index,
      extended: extended,
      backgroundColor: context.colorScheme.surface,
      indicatorColor: accent.withValues(
        alpha: AppInputStyle.config.fillOpacity * 2,
      ),
      // An extended rail already writes every label beside its icon; asking for
      // labels as well is what NavigationRail asserts against.
      labelType: extended ? null : NavigationRailLabelType.all,
      leading: leading,
      trailing: trailing == null
          ? null
          : Expanded(
              child: Align(
                alignment: Alignment.bottomCenter,
                child: trailing,
              ),
            ),
      onDestinationSelected: (i) {
        HapticFeedback.selectionClick();
        onDestinationSelected(i);
      },
      destinations: [
        for (final destination in destinations)
          NavigationRailDestination(
            icon: Icon(destination.icon),
            selectedIcon: Icon(destination.selectedIcon, color: accent),
            label: Text(destination.label),
          ),
      ],
    );
  }
}

/// A [Scaffold] that navigates the way the window is shaped: an [AppNavRail]
/// beside the content on a tablet, an [AppBottomNav] under it on a phone.
///
/// This is the shell a `StatefulShellRoute` builds, and the reason the two nav
/// widgets share one destination type:
///
/// ```dart
/// AppAdaptiveNav(
///   destinations: destinations,
///   index: shell.currentIndex,
///   onDestinationSelected: shell.goBranch,
///   body: shell,
/// )
/// ```
class AppAdaptiveNav extends StatelessWidget {
  const AppAdaptiveNav({
    super.key,
    required this.destinations,
    required this.index,
    required this.onDestinationSelected,
    required this.body,
    this.appBar,
    this.floatingActionButton,
    this.drawer,
    this.extendedRail = false,
    this.variant,
  });

  final List<AppNavDestination> destinations;
  final int index;
  final ValueChanged<int> onDestinationSelected;

  /// The screen itself — on a phone the whole body, on a tablet everything
  /// right of the rail.
  final Widget body;

  final PreferredSizeWidget? appBar;
  final Widget? floatingActionButton;
  final Widget? drawer;

  /// Whether the rail shows its labels beside the icons. Only read on the wide
  /// layout.
  final bool extendedRail;

  /// Null follows [AppInputConfig.defaults].
  final AppInputVariant? variant;

  @override
  Widget build(BuildContext context) {
    // The 600dp short-side breakpoint, so the layout survives a rotation
    // instead of following whichever edge happens to be longer.
    final wide = context.isTablet;

    return Scaffold(
      appBar: appBar,
      drawer: drawer,
      floatingActionButton: floatingActionButton,
      body: wide
          ? Row(
              children: [
                AppNavRail(
                  destinations: destinations,
                  index: index,
                  onDestinationSelected: onDestinationSelected,
                  extended: extendedRail,
                  variant: variant,
                ),
                const VerticalDivider(width: 1),
                Expanded(child: body),
              ],
            )
          : body,
      bottomNavigationBar: wide
          ? null
          : AppBottomNav(
              index: index,
              destinations: destinations,
              onDestinationSelected: onDestinationSelected,
            ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

import './app_button.dart';
import '../../../core/constants/app_constants.dart';
import '../../../core/utils/extensions.dart';

/// The screen's one primary action, wearing [AppButtonVariant] so it matches
/// the buttons inside the screen it floats over.
///
/// ```dart
/// Scaffold(
///   floatingActionButton: AppFab(
///     icon: Icons.add,
///     label: 'New order',        // omit for a circular icon-only FAB
///     onPressed: _create,
///   ),
///   ...
/// )
/// ```
///
/// [isLoading] swaps the icon for a spinner and stops the taps without changing
/// the button's size, so a FAB that starts a request does not resize the screen
/// under it. A null [onPressed] renders it disabled — the same rule the rest of
/// the kit follows.
class AppFab extends StatelessWidget {
  const AppFab({
    super.key,
    required this.icon,
    this.onPressed,
    this.label,
    this.variant = AppButtonVariant.primary,
    this.type = AppButtonType.filled,
    this.isLoading = false,
    this.mini = false,
    this.tooltip,
    this.heroTag,
  });

  final IconData icon;

  /// Pass null to render the FAB disabled.
  final VoidCallback? onPressed;

  /// Turns the circle into an extended pill. Skip it for the icon-only form.
  final String? label;

  final AppButtonVariant variant;

  /// [AppButtonType.filled] is the FAB Material describes;
  /// [AppButtonType.outlined] and [AppButtonType.ghost] give the quieter
  /// version a screen with its own strong content sometimes wants.
  final AppButtonType type;

  final bool isLoading;

  /// The smaller circle, for a dense screen. Ignored by the extended form,
  /// which has a label to fit.
  final bool mini;

  /// Falls back to [label] on the extended form. Worth setting on the
  /// icon-only form, which otherwise says nothing at all to a screen reader.
  final String? tooltip;

  /// Only needed when two FABs can be on screen at once, or across a route
  /// transition: Flutter animates same-tag heroes into each other and throws if
  /// it finds two.
  final Object? heroTag;

  (Color, Color) _colorsOf(BuildContext context) {
    final colorScheme = context.colorScheme;
    final (accent, onAccent) = switch (variant) {
      AppButtonVariant.primary => (colorScheme.primary, colorScheme.onPrimary),
      AppButtonVariant.secondary => (
        colorScheme.secondary,
        colorScheme.onSecondary,
      ),
      AppButtonVariant.tertiary => (
        colorScheme.tertiary,
        colorScheme.onTertiary,
      ),
      AppButtonVariant.danger => (colorScheme.error, colorScheme.onError),
    };

    // Variant picks the color; type only decides how it is applied — the same
    // split AppButton makes.
    return switch (type) {
      AppButtonType.filled => (accent, onAccent),
      AppButtonType.outlined || AppButtonType.ghost => (
        colorScheme.surfaceContainerLowest,
        accent,
      ),
    };
  }

  @override
  Widget build(BuildContext context) {
    final enabled = !isLoading && onPressed != null;
    final (background, foreground) = _colorsOf(context);
    final resolvedBackground = enabled
        ? background
        : background.withValues(alpha: 0.35);

    final child = isLoading
        ? SizedBox.square(
            dimension: AppConstants.iconMedium,
            child: CircularProgressIndicator(
              strokeWidth: 2,
              color: foreground,
            ),
          )
        : Icon(icon, color: foreground);

    void handlePress() {
      HapticFeedback.selectionClick();
      onPressed!();
    }

    final shape = RoundedRectangleBorder(
      borderRadius: AppConstants.borderRadius16,
      side: type == AppButtonType.outlined
          ? BorderSide(color: foreground, width: 1.5)
          : BorderSide.none,
    );

    final resolvedLabel = label;
    if (resolvedLabel == null) {
      return FloatingActionButton(
        onPressed: enabled ? handlePress : null,
        backgroundColor: resolvedBackground,
        foregroundColor: foreground,
        elevation: type == AppButtonType.ghost ? 0 : null,
        mini: mini,
        shape: shape,
        tooltip: tooltip,
        heroTag: heroTag,
        child: child,
      );
    }

    return FloatingActionButton.extended(
      onPressed: enabled ? handlePress : null,
      backgroundColor: resolvedBackground,
      foregroundColor: foreground,
      elevation: type == AppButtonType.ghost ? 0 : null,
      shape: shape,
      tooltip: tooltip ?? resolvedLabel,
      heroTag: heroTag,
      icon: child,
      label: Text(
        resolvedLabel,
        style: context.textTheme.titleSmall?.copyWith(
          color: foreground,
          fontWeight: FontWeight.bold,
        ),
      ),
    );
  }
}

