/// A read-only field holding a start and an end date, opening the calendar
/// range picker.
///
/// ```dart
/// AppDateRangeInput(
///   label: 'Period',
///   initialValue: _period,
///   onChanged: (range) => setState(() => _period = range),
/// )
/// ```
///
/// Unlike [AppDateInput] this does not switch pickers per platform: Cupertino
/// has no range wheel, and two wheels stitched together reads worse than the
/// calendar users of both platforms already know. The [firstDate] / [lastDate]
/// window and [maxDays] are enforced here rather than left to the picker.
class AppDateRangeInput extends StatefulWidget {
  const AppDateRangeInput({
    super.key,
    required this.label,
    this.initialValue,
    this.hint,
    this.separator = ' – ',
    this.firstDate,
    this.lastDate,
    this.maxDays,
    this.enabled = true,
    this.readOnly = false,
    this.required = false,
    this.validator,
    this.autovalidateMode,
    this.onChanged,
    this.onCleared,
    this.prefixIcon,
    this.suffixIcon,
    this.labelMode,
    this.variant,
    this.type,
    this.shape,
    this.size,
    this.textAlign = TextAlign.start,
  });

  final String label;

  /// The range the field starts on. The caller keeps ownership of the value
  /// after that — [onChanged] reports every pick.
  final DateTimeRange? initialValue;

  final String? hint;

  /// What goes between the two dates. An en dash by default, which is what a
  /// range is written with.
  final String separator;

  /// The selectable window. Null is a century either side of today, matching
  /// [AppDateInput].
  final DateTime? firstDate;
  final DateTime? lastDate;

  /// Longest range the field accepts, in days, inclusive of both ends. A pick
  /// wider than this is rejected with a message rather than silently trimmed —
  /// the user chose two dates and deserves to know which rule refused them.
  final int? maxDays;

  final bool enabled;

  /// Styled normally but opens nothing — for a range that is displayed rather
  /// than chosen.
  final bool readOnly;

  /// Marks the label, and — unless [validator] replaces the rule — rejects an
  /// empty field when the form validates.
  final bool required;

  /// Replaces the built-in rule entirely. Receives the current range.
  /// Call [AppDateRangeInput.validate] from inside it to add a rule on top
  /// instead of dropping the required and [maxDays] checks.
  final String? Function(DateTimeRange? range)? validator;

  final AutovalidateMode? autovalidateMode;

  /// Fires with the picked range.
  final ValueChanged<DateTimeRange>? onChanged;

  /// Providing it is what puts the clear button in the field.
  final VoidCallback? onCleared;

  final Widget? prefixIcon;
  final Widget? suffixIcon;

  /// Null follows [AppInputConfig.defaults].
  final AppInputLabelMode? labelMode;
  final AppInputVariant? variant;
  final AppInputType? type;
  final AppInputShape? shape;
  final AppInputSize? size;

  final TextAlign textAlign;

  /// The rule applied when no [validator] is given: a required field holds a
  /// range, and a range is no wider than [maxDays].
  static String? validate(
    DateTimeRange? range, {
    bool required = false,
    int? maxDays,
  }) {
    if (range == null) {
      return required ? 'This field is required' : null;
    }
    if (maxDays != null && range.duration.inDays + 1 > maxDays) {
      return 'Pick a range of $maxDays days or fewer';
    }
    return null;
  }

  @override
  State<AppDateRangeInput> createState() => _AppDateRangeInputState();
}

class _AppDateRangeInputState extends State<AppDateRangeInput> {
  DateTimeRange? _range;

  @override
  void initState() {
    super.initState();
    _range = widget.initialValue;
  }

  @override
  void didUpdateWidget(AppDateRangeInput oldWidget) {
    super.didUpdateWidget(oldWidget);
    // The caller cleared or moved the range from outside — a reset button on
    // the form, a value arriving from a fetch.
    if (widget.initialValue != oldWidget.initialValue) {
      _range = widget.initialValue;
    }
  }

  DateTime get _firstDate =>
      widget.firstDate ??
      DateTime.now().subtract(const Duration(days: 365 * 100));

  DateTime get _lastDate =>
      widget.lastDate ?? DateTime.now().add(const Duration(days: 365 * 100));

  String get _text {
    final range = _range;
    if (range == null) return '';
    return '${range.start.formattedDate}${widget.separator}'
        '${range.end.formattedDate}';
  }

  Future<void> _pick() async {
    HapticFeedback.selectionClick();
    final picked = await showDateRangePicker(
      context: context,
      initialDateRange: _range,
      firstDate: _firstDate,
      lastDate: _lastDate,
      builder: (context, child) => MediaQuery(
        // A range picker is two dates wide already; letting the system text
        // scale grow it as well is what pushes the calendar off the screen.
        data: MediaQuery.of(context).copyWith(textScaler: TextScaler.noScaling),
        child: child!,
      ),
    );
    if (picked == null || !mounted) return;

    HapticFeedback.selectionClick();
    setState(() => _range = picked);
    widget.onChanged?.call(picked);
  }

  void _clear() {
    HapticFeedback.selectionClick();
    setState(() => _range = null);
    widget.onCleared?.call();
  }

  String? _validate() {
    final rule = widget.validator;
    return rule != null
        ? rule(_range)
        : AppDateRangeInput.validate(
            _range,
            required: widget.required,
            maxDays: widget.maxDays,
          );
  }

  Widget? _trailing() {
    if (widget.suffixIcon != null) return widget.suffixIcon;
    if (!widget.enabled || widget.readOnly) return null;

    const calendar = Icon(Icons.date_range_outlined);
    if (widget.onCleared == null || _range == null) return calendar;

    return Row(
      mainAxisSize: MainAxisSize.min,
      children: [
        IconButton(
          onPressed: _clear,
          tooltip: 'Clear',
          icon: const Icon(Icons.close),
        ),
        calendar,
      ],
    );
  }

  @override
  Widget build(BuildContext context) {
    final accent = AppInputStyle.accentOf(context, widget.variant);
    final alignment = AppInputStyle.alignmentOf(widget.textAlign);

    return InputFieldLayout(
      label: widget.label,
      required: widget.required,
      labelMode: widget.labelMode,
      variant: widget.variant,
      size: widget.size,
      textAlign: widget.textAlign,
      // A FormField rather than a TextFormField: the value is a range, and a
      // controller holding its printed form would make the text the truth.
      field: FormField<DateTimeRange>(
        initialValue: _range,
        enabled: widget.enabled,
        autovalidateMode:
            widget.autovalidateMode ?? AppInputStyle.config.autovalidateMode,
        validator: (_) => _validate(),
        builder: (state) => MergeSemantics(
          child: Semantics(
            button: true,
            enabled: widget.enabled && !widget.readOnly,
            child: InkWell(
              onTap: widget.enabled && !widget.readOnly
                  ? () async {
                      await _pick();
                      // Clears the error the moment a range lands, on a form
                      // that validates as it is filled in.
                      if (mounted) state.didChange(_range);
                    }
                  : null,
              child: InputDecorator(
                decoration: AppInputStyle.decoration(
                  context,
                  variant: widget.variant,
                  type: widget.type,
                  shape: widget.shape,
                  size: widget.size,
                  label: widget.label,
                  labelMode: widget.labelMode,
                  required: widget.required,
                  hint: widget.hint,
                  prefixIcon: widget.prefixIcon,
                  suffixIcon: _trailing(),
                  enabled: widget.enabled,
                ).copyWith(errorText: state.errorText),
                isEmpty: _range == null,
                child: _range == null
                    ? null
                    : Align(
                        alignment: alignment,
                        child: Text(
                          _text,
                          textAlign: widget.textAlign,
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: AppInputStyle.textStyle(
                            context,
                            size: widget.size,
                          )?.copyWith(
                            color: accent,
                            fontWeight: FontWeight.bold,
                          ),
                        ),
                      ),
              ),
            ),
          ),
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

import './app_input_style.dart';
import './input_title.dart';
import './search_picker_sheet.dart';
import '../../../core/constants/app_constants.dart';
import '../../../core/utils/extensions.dart';

/// How a multi-select field shows what is in it.
///
/// - [chips]: a removable chip per selection, spilling into "+N" past
///   [AppMultiSelectInput.maxVisibleChips].
/// - [labels]: the labels on one line, comma-separated and ellipsized.
/// - [count]: "3 selected" — for a field whose picks are long or many.
enum AppMultiSelectDisplay { chips, labels, count }

/// [AppDropdownInput]'s plural: the same id/label entity list, any number of
/// them selected, picked in a [SearchPickerSheet] with a checkbox per row.
///
/// ```dart
/// AppMultiSelectInput<TagEntity>(
///   label: 'Tags',
///   items: tags,
///   idOf: (t) => t.id,
///   labelOf: (t) => t.name,
///   selectedIds: _tagIds,
///   required: true,
///   maxSelected: 3,
///   onChanged: (ids) => setState(() => _tagIds = ids),
/// )
/// ```
///
/// The caller owns the selection, as it does on every other field in the
/// family: [onChanged] hands back the whole new list rather than a diff, so the
/// field never holds a second copy of the truth.
class AppMultiSelectInput<T> extends StatelessWidget {
  const AppMultiSelectInput({
    super.key,
    required this.label,
    required this.items,
    required this.idOf,
    required this.labelOf,
    required this.onChanged,
    this.selectedIds = const [],
    this.onSelected,
    this.hint = 'Select options',
    this.enabled = true,
    this.required = false,
    this.minSelected,
    this.maxSelected,
    this.validator,
    this.autovalidateMode,
    this.display = AppMultiSelectDisplay.chips,
    this.maxVisibleChips = 3,
    this.searchHint = 'Search',
    this.searchTitle,
    this.leadingOf,
    this.trailingLabelOf,
    this.filter,
    this.emptyLabel,
    this.prefixIcon,
    this.suffixIcon,
    this.labelMode,
    this.variant,
    this.type,
    this.shape,
    this.size,
  });

  final String label;
  final List<T> items;

  /// Extract the id from an item. Ids are what the selection is made of, so
  /// they must be unique across [items] — a duplicate trips an assert.
  final String Function(T item) idOf;

  /// Extract the display label from an item.
  final String Function(T item) labelOf;

  /// Called with the complete new selection, in the order the items appear in
  /// [items] — not in the order they were ticked, which no caller wants to
  /// store.
  final ValueChanged<List<String>> onChanged;

  /// The current selection.
  final List<String> selectedIds;

  /// Called with the items themselves, alongside [onChanged].
  final ValueChanged<List<T>>? onSelected;

  final String hint;
  final bool enabled;

  /// Marks the label, and — unless [validator] replaces the rule — rejects an
  /// empty selection when the form validates.
  final bool required;

  /// Floor and ceiling on how many may be picked. [maxSelected] is enforced in
  /// the sheet as well: past it the unticked rows stop responding rather than
  /// letting the user pick something the form will reject.
  final int? minSelected;
  final int? maxSelected;

  /// Replaces the built-in rule entirely. Receives the selected ids.
  /// Call [AppMultiSelectInput.validate] from inside it to add a rule on top
  /// instead of dropping the required, min and max checks.
  final String? Function(List<String> ids)? validator;

  /// When the field validates itself. Null follows the config.
  final AutovalidateMode? autovalidateMode;

  final AppMultiSelectDisplay display;

  /// How many chips are drawn before the rest become a "+N" chip. Only read by
  /// [AppMultiSelectDisplay.chips].
  final int maxVisibleChips;

  final String searchHint;

  /// Heading over the sheet. Defaults to [label].
  final String? searchTitle;

  /// Optional leading widget per row in the sheet.
  final Widget Function(T item)? leadingOf;

  /// Optional dimmed text at the end of a sheet row.
  final String Function(T item)? trailingLabelOf;

  /// Replaces the sheet's default filter, a case-insensitive `contains` over
  /// [labelOf]. Returns the rows to show in the order to show them.
  final List<T> Function(List<T> items, String query)? filter;

  /// Shown in the sheet in place of the list when there is nothing to show.
  final String? emptyLabel;

  final Widget? prefixIcon;

  /// Replaces the chevron — and with it the clear button.
  final Widget? suffixIcon;

  /// Null follows [AppInputConfig.defaults].
  final AppInputLabelMode? labelMode;
  final AppInputVariant? variant;
  final AppInputType? type;
  final AppInputShape? shape;
  final AppInputSize? size;

  /// The rule applied when no [validator] is given: a required field holds at
  /// least one id, and the selection sits inside [min] and [max].
  ///
  /// Exposed so a custom [validator] can layer on top of it:
  ///
  ///   validator: (ids) =>
  ///       AppMultiSelectInput.validate(ids, required: true) ??
  ///       (ids.contains('archived') ? 'That tag is closed' : null),
  static String? validate(
    List<String> ids, {
    bool required = false,
    int? min,
    int? max,
  }) {
    if (required && ids.isEmpty) return 'This field is required';
    // An empty optional field is not "fewer than min" — it is untouched, and
    // saying "pick at least 2" to someone who picked none is noise.
    if (min != null && ids.isNotEmpty && ids.length < min) {
      return 'Pick at least $min';
    }
    if (max != null && ids.length > max) return 'Pick no more than $max';
    return null;
  }

  /// The items the selection points at, in [items] order.
  List<T> get _selected => [
    for (final item in items)
      if (selectedIds.contains(idOf(item))) item,
  ];

  String? _validate(List<String> ids) {
    final rule = validator;
    return rule != null
        ? rule(ids)
        : validate(
            ids,
            required: required,
            min: minSelected,
            max: maxSelected,
          );
  }

  Future<void> _openSheet(
    BuildContext context,
    FormFieldState<List<String>> state,
  ) async {
    final picked = await SearchPickerSheet.showMulti<T>(
      context,
      title: searchTitle ?? label,
      searchHint: searchHint,
      items: items,
      idOf: idOf,
      labelOf: labelOf,
      selectedIds: selectedIds,
      maxSelected: maxSelected,
      leadingOf: leadingOf,
      trailingLabelOf: trailingLabelOf,
      filter: filter,
      emptyLabel:
          emptyLabel ??
          (items.isEmpty
              ? 'Nothing to choose from'
              : 'Nothing matches that search'),
      variant: variant,
    );
    // Null is a dismissed sheet, which leaves the selection alone. An empty
    // list is a confirmed "none of them", which does not.
    if (picked == null) return;
    _report(picked, state);
  }

  void _report(List<T> picked, FormFieldState<List<String>> state) {
    final ids = [for (final item in picked) idOf(item)];
    // Marks the field as interacted with, so a form set to validate on
    // interaction clears its error the moment a selection lands.
    state.didChange(ids);
    onChanged(ids);
    onSelected?.call(picked);
  }

  void _remove(T item, FormFieldState<List<String>> state) {
    HapticFeedback.selectionClick();
    final id = idOf(item);
    _report([
      for (final other in _selected)
        if (idOf(other) != id) other,
    ], state);
  }

  /// What sits at the end of the field: the caller's suffix, else the clear
  /// button once there is something to clear, ahead of the chevron.
  Widget? _trailing(FormFieldState<List<String>> state) {
    if (suffixIcon != null) return suffixIcon;
    if (!enabled) return null;

    const chevron = Icon(Icons.keyboard_arrow_down);
    if (selectedIds.isEmpty) return chevron;

    return Row(
      mainAxisSize: MainAxisSize.min,
      children: [
        IconButton(
          onPressed: () {
            HapticFeedback.selectionClick();
            _report(const [], state);
          },
          tooltip: 'Clear',
          icon: const Icon(Icons.close),
        ),
        chevron,
      ],
    );
  }

  @override
  Widget build(BuildContext context) {
    assert(
      items.map(idOf).toSet().length == items.length,
      'AppMultiSelectInput<$T>: idOf returned the same id for more than one '
      'item. Ids are what the selection is made of, so they have to be unique.',
    );

    return InputFieldLayout(
      label: label,
      required: required,
      labelMode: labelMode,
      variant: variant,
      size: size,
      field: FormField<List<String>>(
        initialValue: selectedIds,
        enabled: enabled,
        autovalidateMode:
            autovalidateMode ?? AppInputStyle.config.autovalidateMode,
        // Judged on [selectedIds] rather than on the value this FormField holds:
        // the caller owns the selection, so its answer is the true one even
        // before a rebuild has reached here.
        validator: (_) => _validate(selectedIds),
        builder: (state) => MergeSemantics(
          child: Semantics(
            button: true,
            enabled: enabled,
            child: InkWell(
              onTap: enabled ? () => _openSheet(context, state) : null,
              borderRadius: AppConstants.borderRadius12,
              child: InputDecorator(
                decoration: AppInputStyle.decoration(
                  context,
                  variant: variant,
                  type: type,
                  shape: shape,
                  size: size,
                  label: label,
                  labelMode: labelMode,
                  required: required,
                  hint: hint,
                  prefixIcon: prefixIcon,
                  suffixIcon: _trailing(state),
                  enabled: enabled,
                ).copyWith(errorText: state.errorText),
                isEmpty: selectedIds.isEmpty,
                child: selectedIds.isEmpty ? null : _value(context, state),
              ),
            ),
          ),
        ),
      ),
    );
  }

  Widget _value(BuildContext context, FormFieldState<List<String>> state) {
    final accent = AppInputStyle.accentOf(context, variant);
    final selected = _selected;
    final valueStyle = AppInputStyle.textStyle(context, size: size)?.copyWith(
      color: accent,
      fontWeight: FontWeight.bold,
    );

    return switch (display) {
      AppMultiSelectDisplay.count => Text(
        '${selected.length} selected',
        style: valueStyle,
      ),
      AppMultiSelectDisplay.labels => Text(
        [for (final item in selected) labelOf(item)].join(', '),
        maxLines: 1,
        overflow: TextOverflow.ellipsis,
        style: valueStyle,
      ),
      AppMultiSelectDisplay.chips => _chips(context, selected, state, accent),
    };
  }

  Widget _chips(
    BuildContext context,
    List<T> selected,
    FormFieldState<List<String>> state,
    Color accent,
  ) {
    final overflow = selected.length - maxVisibleChips;
    final shown = overflow > 0 ? selected.take(maxVisibleChips) : selected;

    return Wrap(
      spacing: AppConstants.space4,
      runSpacing: AppConstants.space4,
      children: [
        for (final item in shown)
          // The chip's own delete button is the shortest path to dropping one
          // pick, and it keeps the sheet for the case where several change.
          InputChip(
            label: Text(labelOf(item)),
            labelStyle: context.textTheme.bodySmall?.copyWith(color: accent),
            backgroundColor: accent.withValues(
              alpha: AppInputStyle.config.fillOpacity * 2,
            ),
            side: BorderSide.none,
            visualDensity: VisualDensity.compact,
            deleteIcon: const Icon(Icons.close, size: AppConstants.iconSmall),
            deleteIconColor: accent,
            onDeleted: enabled ? () => _remove(item, state) : null,
          ),
        if (overflow > 0)
          Padding(
            padding: const EdgeInsets.only(top: AppConstants.space4),
            child: Text(
              '+$overflow',
              style: context.textTheme.bodySmall?.copyWith(
                color: context.colorScheme.onSurfaceVariant,
              ),
            ),
          ),
      ],
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import '../../../core/constants/app_constants.dart';

/// Feedback status for [AppToast].
enum AppToastType { success, error, warning, info }

/// One consistent feedback surface for the whole app.
///
/// ```dart
/// AppToast.success(context, 'Saved');
/// AppToast.show(
///   context,
///   'Check your connection and try again.',
///   title: 'Could not save',
///   type: AppToastType.error,
///   actionLabel: 'Retry',
///   onAction: _save,
/// );
/// ```
///
/// From a Riverpod notifier you already have a context inside `ref.listen` —
/// or use `ref.listenAction`, which calls this for you.
///
/// **It draws its own card.** The [SnackBar] underneath is only a positioned,
/// dismissible, self-timing slot: transparent, unelevated and unpadded. That is
/// what buys the border, the tinted surface, the soft shadow and the layout
/// below — a SnackBar can be given a color and a shape, but not an outline, and
/// an outline is most of what makes this read as a card rather than as a grey
/// bar at the bottom of the screen.
class AppToast {
  const AppToast._();

  /// How much of the status color tints the card's surface. Enough to be felt,
  /// not enough to fight the text on it.
  static const double _surfaceTint = 0.07;

  /// The outline, which is what gives the card an edge in both themes — a
  /// shadow alone disappears against a dark background.
  static const double _borderOpacity = 0.30;

  /// The icon chip's fill. Matches [AppLeadingIcon]'s tonal fill, so the two
  /// read as siblings.
  static const double _chipFill = 0.12;

  /// Widest the card gets. Past this a toast on a tablet becomes a banner
  /// stretched across the screen, and the eye has to travel to read six words.
  static const double _maxWidth = 480;

  static void show(
    BuildContext context,
    String message, {
    AppToastType type = AppToastType.info,
    String? title,
    Duration duration = const Duration(seconds: 4),
    String? actionLabel,
    VoidCallback? onAction,
    bool showClose = false,
  }) {
    _feedback(type);

    final messenger = ScaffoldMessenger.of(context)..hideCurrentSnackBar();
    messenger.showSnackBar(
      SnackBar(
        behavior: SnackBarBehavior.floating,
        backgroundColor: Colors.transparent,
        elevation: 0,
        padding: EdgeInsets.zero,
        duration: duration,
        margin: const EdgeInsets.all(AppConstants.space12),
        // Flick it away sideways, which is what a card at the edge of the
        // screen invites; the default is a downward drag into the bezel.
        dismissDirection: DismissDirection.horizontal,
        content: Align(
          // Bottom-center on a wide window rather than pinned to one corner.
          child: ConstrainedBox(
            constraints: const BoxConstraints(maxWidth: _maxWidth),
            // The card resolves its own colors from the context it is built in.
            // Passing them down from here looks equivalent and is not: the
            // SnackBar builds a frame later, and a theme that changed in
            // between would leave a light-palette green on a dark card.
            child: _ToastCard(
              message: message,
              title: title,
              type: type,
              actionLabel: actionLabel,
              onAction: onAction,
              showClose: showClose,
            ),
          ),
        ),
      ),
    );
  }

  static void success(BuildContext context, String message, {String? title}) =>
      show(context, message, title: title, type: AppToastType.success);

  static void error(BuildContext context, String message, {String? title}) =>
      show(context, message, title: title, type: AppToastType.error);

  static void warning(BuildContext context, String message, {String? title}) =>
      show(context, message, title: title, type: AppToastType.warning);

  static void info(BuildContext context, String message, {String? title}) =>
      show(context, message, title: title, type: AppToastType.info);

  /// Takes the current toast off screen early — for a screen that is about to
  /// be popped, or an action whose result has already been shown another way.
  static void dismiss(BuildContext context) =>
      ScaffoldMessenger.of(context).hideCurrentSnackBar();

  /// A toast usually lands while the user is looking somewhere else, so it
  /// says what happened by feel as well as by color — the worse the news, the
  /// heavier the tap.
  static void _feedback(AppToastType type) => switch (type) {
        AppToastType.success => HapticFeedback.lightImpact(),
        AppToastType.warning => HapticFeedback.mediumImpact(),
        AppToastType.error => HapticFeedback.heavyImpact(),
        AppToastType.info => HapticFeedback.selectionClick(),
      };

  static (Color, IconData) _resolve(AppToastType type, bool isDark) =>
      switch (type) {
        AppToastType.success => (
            isDark ? AppConstants.successDark : AppConstants.success,
            Icons.check_circle_outline,
          ),
        AppToastType.error => (
            isDark ? AppConstants.errorDark : AppConstants.error,
            Icons.error_outline,
          ),
        AppToastType.warning => (
            isDark ? AppConstants.warningDark : AppConstants.warning,
            Icons.warning_amber_rounded,
          ),
        AppToastType.info => (
            isDark ? AppConstants.infoDark : AppConstants.info,
            Icons.info_outline,
          ),
      };
}

/// The card [AppToast] puts inside the SnackBar. Private on purpose: a toast is
/// shown through [AppToast.show], never built by hand.
class _ToastCard extends StatelessWidget {
  const _ToastCard({
    required this.message,
    required this.title,
    required this.type,
    required this.actionLabel,
    required this.onAction,
    required this.showClose,
  });

  final String message;
  final String? title;
  final AppToastType type;
  final String? actionLabel;
  final VoidCallback? onAction;
  final bool showClose;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final colorScheme = theme.colorScheme;
    final isDark = theme.brightness == Brightness.dark;
    final (accent, icon) = AppToast._resolve(type, isDark);
    final heading = title;
    final hasAction = actionLabel != null && onAction != null;

    return Container(
      padding: const EdgeInsets.all(AppConstants.space12),
      decoration: BoxDecoration(
        // Tinted rather than colored: the status is carried by the icon and the
        // outline, so the text keeps the contrast the theme guarantees it.
        color: Color.alphaBlend(
          accent.withValues(alpha: AppToast._surfaceTint),
          isDark
              ? colorScheme.surfaceContainerHighest
              : colorScheme.surfaceContainerLowest,
        ),
        borderRadius: AppConstants.borderRadius16,
        border: Border.all(
          color: accent.withValues(alpha: AppToast._borderOpacity),
        ),
        boxShadow: [
          BoxShadow(
            color: colorScheme.shadow.withValues(alpha: isDark ? 0.45 : 0.12),
            blurRadius: AppConstants.space24,
            offset: const Offset(0, 6),
          ),
        ],
      ),
      child: Row(
        // Top, not center: with a title and two lines of body the icon belongs
        // beside the first line, not floating halfway down the card.
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Container(
            padding: const EdgeInsets.all(AppConstants.space8),
            decoration: BoxDecoration(
              color: accent.withValues(alpha: AppToast._chipFill),
              borderRadius: AppConstants.borderRadius8,
            ),
            child: Icon(icon, color: accent, size: AppConstants.iconSmall),
          ),
          const SizedBox(width: AppConstants.space12),
          Expanded(
            child: Padding(
              // Centers a single line against the icon chip without moving a
              // two-line one off the top.
              padding: const EdgeInsets.symmetric(vertical: AppConstants.space4),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                mainAxisSize: MainAxisSize.min,
                children: [
                  if (heading != null)
                    Text(
                      heading,
                      style: theme.textTheme.titleSmall?.copyWith(
                        color: colorScheme.onSurface,
                        fontWeight: FontWeight.bold,
                      ),
                    ),
                  Text(
                    message,
                    // A toast is glanceable by definition; anything longer than
                    // this belongs in an AppBanner, which persists.
                    maxLines: 3,
                    overflow: TextOverflow.ellipsis,
                    style: theme.textTheme.bodyMedium?.copyWith(
                      color: heading == null
                          ? colorScheme.onSurface
                          : colorScheme.onSurfaceVariant,
                    ),
                  ),
                ],
              ),
            ),
          ),
          if (hasAction) ...[
            const SizedBox(width: AppConstants.space8),
            TextButton(
              onPressed: () {
                HapticFeedback.selectionClick();
                ScaffoldMessenger.of(context).hideCurrentSnackBar();
                onAction!();
              },
              style: TextButton.styleFrom(
                foregroundColor: accent,
                visualDensity: VisualDensity.compact,
                padding: const EdgeInsets.symmetric(
                  horizontal: AppConstants.space12,
                ),
                shape: RoundedRectangleBorder(
                  borderRadius: AppConstants.borderRadius8,
                ),
              ),
              child: Text(
                actionLabel!,
                style: theme.textTheme.labelLarge?.copyWith(
                  color: accent,
                  fontWeight: FontWeight.bold,
                ),
              ),
            ),
          ],
          if (showClose)
            IconButton(
              onPressed: () =>
                  ScaffoldMessenger.of(context).hideCurrentSnackBar(),
              icon: const Icon(Icons.close, size: AppConstants.iconSmall),
              color: colorScheme.onSurfaceVariant,
              visualDensity: VisualDensity.compact,
              tooltip: 'Dismiss',
            ),
        ],
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import '../../../core/constants/app_constants.dart';
import '../../../core/utils/extensions.dart';

/// A settings/menu row: an optional leading widget (e.g. AppLeadingIcon), a
/// title with optional subtitle, and an optional trailing widget (a value
/// Text, an AppSwitch, a chevron...). Tapping anywhere fires [onTap].
class AppListTile extends StatelessWidget {
  const AppListTile({
    super.key,
    required this.title,
    this.subtitle,
    this.leading,
    this.trailing,
    this.onTap,
    this.showChevron = false,
    this.danger = false,
  });

  final String title;
  final String? subtitle;
  final Widget? leading;
  final Widget? trailing;
  final VoidCallback? onTap;

  /// Appends a trailing chevron when [trailing] is null - the usual "drills
  /// into another screen" affordance.
  final bool showChevron;

  /// Tints the title in the error color, for destructive rows like
  /// "Delete account" / "Log out".
  final bool danger;

  @override
  Widget build(BuildContext context) {
    final theme = context.theme;
    final titleColor =
        danger ? theme.colorScheme.error : theme.colorScheme.onSurface;

    Widget? resolvedTrailing = trailing;
    if (resolvedTrailing == null && showChevron) {
      resolvedTrailing = Icon(
        Icons.chevron_right,
        color: theme.colorScheme.onSurfaceVariant,
        size: AppConstants.iconMedium,
      );
    }

    return InkWell(
      borderRadius: AppConstants.borderRadius12,
      onTap: onTap == null
          ? null
          : () {
              HapticFeedback.selectionClick();
              onTap!();
            },
      child: Padding(
        padding: const EdgeInsets.symmetric(
          horizontal: AppConstants.space12,
          vertical: AppConstants.space12,
        ),
        child: Row(
          children: [
            if (leading != null) ...[
              leading!,
              const SizedBox(width: AppConstants.space12),
            ],
            Expanded(
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    title,
                    softWrap: true,
                    maxLines: 2,
                    style: theme.textTheme.bodyLarge?.copyWith(
                      color: titleColor,
                      overflow: TextOverflow.ellipsis,
                    ),
                  ),
                  if (subtitle != null) ...[
                    const SizedBox(height: 2),
                    Text(
                      subtitle!,
                      style: theme.textTheme.bodySmall?.copyWith(
                        color: theme.colorScheme.onSurfaceVariant,
                      ),
                    ),
                  ],
                ],
              ),
            ),
            if (resolvedTrailing != null) ...[
              const SizedBox(width: AppConstants.space12),
              resolvedTrailing,
            ],
          ],
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import '../../../core/constants/app_constants.dart';
import '../../../core/utils/extensions.dart';

/// Fill treatment of [AppCard].
/// - [elevated]: soft shadow, raised off the surface.
/// - [filled]: sits on a tonal surface, no border (the default).
/// - [outlined]: flat with a hairline border.
enum AppCardType { elevated, filled, outlined }

/// A themed surface container. Provide [onTap] to make the whole card tappable.
class AppCard extends StatelessWidget {
  const AppCard({
    super.key,
    required this.child,
    this.type = AppCardType.filled,
    this.padding = AppConstants.padding16,
    this.onTap,
    this.clipBehavior = Clip.antiAlias,
  });

  final Widget child;
  final AppCardType type;
  final EdgeInsetsGeometry padding;
  final VoidCallback? onTap;

  /// How the child is clipped to the card's rounded corners. Defaults to
  /// [Clip.antiAlias] so an interactive child (e.g. an AppListTile with
  /// [padding] set to [EdgeInsets.zero]) keeps its ripple inside the corners.
  final Clip clipBehavior;

  @override
  Widget build(BuildContext context) {
    final theme = context.theme;
    final radius = AppConstants.borderRadius16;

    final decoration = switch (type) {
      AppCardType.elevated => BoxDecoration(
          color: theme.colorScheme.surfaceContainerLowest,
          borderRadius: radius,
          boxShadow: [
            BoxShadow(
              color: Colors.black.withValues(alpha: 0.08),
              blurRadius: 16,
              offset: const Offset(0, 4),
            ),
          ],
        ),
      AppCardType.filled => BoxDecoration(
          color: theme.colorScheme.surfaceContainerLowest,
          borderRadius: radius,
        ),
      AppCardType.outlined => BoxDecoration(
          color: Colors.transparent,
          borderRadius: radius,
          border: Border.all(color: theme.colorScheme.outlineVariant),
        ),
    };

    final content = Container(
      clipBehavior: clipBehavior,
      decoration: decoration,
      child: Padding(padding: padding, child: child),
    );

    if (onTap == null) return content;
    return InkWell(
      borderRadius: radius,
      onTap: () {
        HapticFeedback.selectionClick();
        onTap!();
      },
      child: content,
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import '../../../core/utils/extensions.dart';

/// A single destination for [AppBottomNav].
class AppNavDestination {
  const AppNavDestination({
    required this.icon,
    required this.selectedIcon,
    required this.label,
  });

  final IconData icon;
  final IconData selectedIcon;
  final String label;
}

/// A themed [NavigationBar] wrapper. Feed it the current [index], the
/// [destinations], and an [onDestinationSelected] callback. For go_router,
/// drive [index] from a StatefulShellRoute and switch branch in the callback.
class AppBottomNav extends StatelessWidget {
  const AppBottomNav({
    super.key,
    required this.index,
    required this.destinations,
    required this.onDestinationSelected,
  });

  final int index;
  final List<AppNavDestination> destinations;
  final ValueChanged<int> onDestinationSelected;

  @override
  Widget build(BuildContext context) {
    final theme = context.theme;
    return NavigationBar(
      selectedIndex: index,
      backgroundColor: theme.colorScheme.surface,
      indicatorColor: theme.colorScheme.primary.withValues(alpha: 0.12),
      onDestinationSelected: (i) {
        HapticFeedback.selectionClick();
        onDestinationSelected(i);
      },
      destinations: [
        for (final d in destinations)
          NavigationDestination(
            icon: Icon(d.icon),
            selectedIcon:
                Icon(d.selectedIcon, color: theme.colorScheme.primary),
            label: d.label,
          ),
      ],
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import './app_checkbox.dart';
import './app_input_style.dart';
import './input_title.dart';
import '../../../core/constants/app_constants.dart';
import '../../../core/utils/extensions.dart';

/// [AppCheckbox] paired with a tappable label (and optional subtitle), the
/// whole row toggling the value — not just the checkbox square.
///
/// `required: true` makes it the "accept the terms" checkbox: a `Form` refuses
/// to validate until it is ticked, and says so under the row.
class AppCheckboxLabel extends StatelessWidget {
  const AppCheckboxLabel({
    super.key,
    required this.label,
    required this.value,
    required this.onChanged,
    this.subtitle,
    this.required = false,
    this.requiredError = 'This box must be ticked',
    this.validator,
    this.autovalidateMode,
    this.variant,
    this.size,
    this.shape,
  });

  final String label;
  final String? subtitle;
  final bool value;

  /// Pass null to render the whole row disabled.
  final ValueChanged<bool>? onChanged;

  /// Marks the row and refuses to validate until it is ticked.
  final bool required;

  /// What a [required] row says when it is still unticked.
  final String requiredError;

  /// Replaces the built-in rule entirely. Returning null means valid.
  final String? Function(bool value)? validator;

  /// When the row validates itself. Null follows the config.
  final AutovalidateMode? autovalidateMode;

  final AppInputVariant? variant;
  final AppInputSize? size;
  final AppInputShape? shape;

  /// The rule in force: the caller's, else the required check, else nothing to
  /// enforce at all.
  String? Function(bool value)? get _rule {
    if (validator != null) return validator;
    if (!required) return null;
    return (value) => value ? null : requiredError;
  }

  @override
  Widget build(BuildContext context) {
    final textTheme = context.textTheme;
    final fontSize = AppInputStyle.configOf(size).fontSize;
    final enabled = onChanged != null;

    return SelectionFormField<bool>(
      value: value,
      validator: _rule,
      enabled: enabled,
      autovalidateMode: autovalidateMode,
      builder: (state) {
        void toggle(bool next) {
          HapticFeedback.selectionClick();
          // Tells the FormField it has been interacted with, so a form set to
          // validate on interaction drops the error as soon as it is ticked.
          state.didChange(next);
          onChanged!(next);
        }

        return InkWell(
          borderRadius: AppConstants.borderRadius8,
          // The square has its own haptic in AppCheckbox, so this one only
          // covers the rest of the row — one buzz either way.
          onTap: enabled ? () => toggle(!value) : null,
          child: Padding(
            padding: const EdgeInsets.symmetric(vertical: AppConstants.space4),
            child: Row(
              crossAxisAlignment: CrossAxisAlignment.center,
              children: [
                AppCheckbox(
                  value: value,
                  onChanged: enabled ? (v) => toggle(v ?? false) : null,
                  variant: variant,
                  size: size,
                  shape: shape,
                ),
                const SizedBox(width: AppConstants.space8),
                Expanded(
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        label,
                        style: textTheme.bodyLarge?.copyWith(
                          fontSize: fontSize,
                          color: enabled
                              ? null
                              : context.colorScheme.onSurface.withValues(
                                  alpha: AppInputStyle.config.disabledOpacity,
                                ),
                        ),
                      ),
                      if (subtitle != null)
                        Text(
                          subtitle!,
                          style: textTheme.bodySmall?.copyWith(
                            color: context.colorScheme.onSurfaceVariant,
                          ),
                        ),
                    ],
                  ),
                ),
              ],
            ),
          ),
        );
      },
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
